INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Hi, I''m Linh!', 'Introducing yourself', 'A1', '{"title":"Hi, I''m Linh!","summary_vi":"Bạn sẽ luyện giới thiệu bản thân: tên, tuổi, nơi ở và sở thích.","sentences":["Hello, my name is Linh.","I am twenty years old.","I live in Hanoi with my family.","I am a student at a big university.","I like music and I love coffee.","Every day, I study English for one hour.","I want to make new friends.","Nice to meet you!"],"vocabulary":[{"word":"name","ipa":"/neɪm/","pos":"noun","meaning_vi":"tên","example":"What is your name?"},{"word":"years old","ipa":"/jɪrz oʊld/","pos":"phrase","meaning_vi":"tuổi","example":"My brother is ten years old."},{"word":"live","ipa":"/lɪv/","pos":"verb","meaning_vi":"sống, ở","example":"They live in a small town."},{"word":"student","ipa":"/ˈstuːdnt/","pos":"noun","meaning_vi":"học sinh, sinh viên","example":"She is a good student."},{"word":"university","ipa":"/ˌjuːnɪˈvɜːrsəti/","pos":"noun","meaning_vi":"trường đại học","example":"His university is near the river."},{"word":"friends","ipa":"/frendz/","pos":"noun","meaning_vi":"những người bạn","example":"I play games with my friends."},{"word":"Nice to meet you","ipa":"/naɪs tuː miːt juː/","pos":"phrase","meaning_vi":"Rất vui được gặp bạn","example":"Hello, Tom. Nice to meet you."}],"questions":[{"question":"How old is Linh?","options":["Eighteen","Twenty","Twenty-five","Thirty"],"answer_index":1,"explanation_vi":"Linh nói: I am twenty years old."},{"question":"Where does Linh live?","options":["In Da Nang","In Hoi An","In London","In Hanoi"],"answer_index":3,"explanation_vi":"Linh sống ở Hanoi cùng gia đình."},{"question":"What is Linh''s job?","options":["She is a teacher","She is a student","She is a doctor","She is a waitress"],"answer_index":1,"explanation_vi":"Linh là sinh viên ở một trường đại học lớn."},{"question":"What does Linh want to do?","options":["Make new friends","Learn music","Drink more coffee","Move to a new city"],"answer_index":0,"explanation_vi":"Cô ấy nói: I want to make new friends."}]}', 'course', 1, 'a1-introduce-yourself', 'people', 1)
