INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Dinner at Seven', 'My family', 'A1', '{"title":"Dinner at Seven","summary_vi":"Bạn sẽ luyện nói về các thành viên trong gia đình và bữa tối chung.","sentences":["This is my family.","My father is a teacher.","My mother works in a small shop.","I have one sister and one brother.","My sister is ten years old.","My brother plays football every day.","We eat dinner together at seven.","I love my family very much."],"vocabulary":[{"word":"family","ipa":"/ˈfæməli/","pos":"noun","meaning_vi":"gia đình","example":"Her family is very friendly."},{"word":"father","ipa":"/ˈfɑːðər/","pos":"noun","meaning_vi":"bố, cha","example":"My father drives a red car."},{"word":"mother","ipa":"/ˈmʌðər/","pos":"noun","meaning_vi":"mẹ","example":"His mother makes great soup."},{"word":"teacher","ipa":"/ˈtiːtʃər/","pos":"noun","meaning_vi":"giáo viên","example":"The teacher is in the classroom."},{"word":"sister","ipa":"/ˈsɪstər/","pos":"noun","meaning_vi":"chị, em gái","example":"My sister likes to draw."},{"word":"brother","ipa":"/ˈbrʌðər/","pos":"noun","meaning_vi":"anh, em trai","example":"Her brother has a new bike."},{"word":"together","ipa":"/təˈɡeðər/","pos":"adverb","meaning_vi":"cùng nhau","example":"We walk to school together."},{"word":"dinner","ipa":"/ˈdɪnər/","pos":"noun","meaning_vi":"bữa tối","example":"Dinner is ready at six."}],"questions":[{"question":"What does the speaker''s father do?","options":["He is a teacher","He works in a shop","He plays football","He is a cook"],"answer_index":0,"explanation_vi":"Bố của người nói là giáo viên."},{"question":"Where does the mother work?","options":["In a school","In a big office","In a small shop","In a hospital"],"answer_index":2,"explanation_vi":"Mẹ làm việc ở một cửa hàng nhỏ."},{"question":"How many brothers and sisters does the speaker have?","options":["One sister only","Two sisters","Two brothers","One sister and one brother"],"answer_index":3,"explanation_vi":"Người nói có một chị/em gái và một anh/em trai."},{"question":"When does the family eat dinner?","options":["At six","At seven","At eight","At nine"],"answer_index":1,"explanation_vi":"Cả nhà ăn tối cùng nhau lúc bảy giờ."}]}', 'course', 1, 'a1-my-family', 'people', 2)
