INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'From Six to Ten', 'A day in my life', 'A1', '{"title":"From Six to Ten","summary_vi":"Bạn sẽ luyện kể về một ngày bình thường từ sáng đến tối.","sentences":["I get up at six o''clock.","I brush my teeth and take a shower.","Then I eat breakfast with my mother.","I go to school by bus.","Classes start at eight.","After school, I do my homework.","In the evening, I watch TV.","I go to bed at ten."],"vocabulary":[{"word":"get up","ipa":"/ɡet ʌp/","pos":"phrase","meaning_vi":"thức dậy","example":"I get up early on Monday."},{"word":"take a shower","ipa":"/teɪk ə ˈʃaʊər/","pos":"phrase","meaning_vi":"tắm vòi sen","example":"Please take a shower before dinner."},{"word":"breakfast","ipa":"/ˈbrekfəst/","pos":"noun","meaning_vi":"bữa sáng","example":"Breakfast is my favorite meal."},{"word":"school","ipa":"/skuːl/","pos":"noun","meaning_vi":"trường học","example":"Her school is very big."},{"word":"by bus","ipa":"/baɪ bʌs/","pos":"phrase","meaning_vi":"bằng xe buýt","example":"My uncle goes to work by bus."},{"word":"homework","ipa":"/ˈhoʊmwɜːrk/","pos":"noun","meaning_vi":"bài tập về nhà","example":"I finish my homework at home."},{"word":"evening","ipa":"/ˈiːvnɪŋ/","pos":"noun","meaning_vi":"buổi tối","example":"We walk in the park in the evening."},{"word":"go to bed","ipa":"/ɡoʊ tuː bed/","pos":"phrase","meaning_vi":"đi ngủ","example":"The children go to bed at nine."}],"questions":[{"question":"What time does the speaker get up?","options":["At five","At seven","At eight","At six"],"answer_index":3,"explanation_vi":"Người nói thức dậy lúc sáu giờ."},{"question":"How does the speaker go to school?","options":["By bus","By bike","On foot","By car"],"answer_index":0,"explanation_vi":"Câu chuyện nói: I go to school by bus."},{"question":"What does the speaker do after school?","options":["Plays football","Watches TV","Does homework","Goes to bed"],"answer_index":2,"explanation_vi":"Sau giờ học, người nói làm bài tập về nhà."},{"question":"When does the speaker go to bed?","options":["At nine","At ten","At eleven","At midnight"],"answer_index":1,"explanation_vi":"Người nói đi ngủ lúc mười giờ."}]}', 'course', 1, 'a1-my-day', 'daily', 3)
