INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Coffee and Cake in Da Nang', 'Ordering at a café', 'A1', '{"title":"Coffee and Cake in Da Nang","summary_vi":"Bạn sẽ luyện gọi đồ uống, đồ ăn và thanh toán ở quán cà phê.","sentences":["Minh and Anna are in a café in Da Nang.","A waiter comes to their table.","Anna asks for a cup of tea.","Minh wants a coffee with milk.","He also orders a chocolate cake.","The cake is small, but it looks delicious.","They pay at the counter.","The bill is eighty thousand dong."],"vocabulary":[{"word":"waiter","ipa":"/ˈweɪtər/","pos":"noun","meaning_vi":"người phục vụ nam","example":"The waiter brings the menu."},{"word":"table","ipa":"/ˈteɪbl/","pos":"noun","meaning_vi":"cái bàn","example":"We sit at a table by the window."},{"word":"a cup of tea","ipa":"/ə kʌp əv tiː/","pos":"phrase","meaning_vi":"một tách trà","example":"I drink a cup of tea in the morning."},{"word":"coffee","ipa":"/ˈkɔːfi/","pos":"noun","meaning_vi":"cà phê","example":"This coffee is hot and strong."},{"word":"orders","ipa":"/ˈɔːrdərz/","pos":"verb","meaning_vi":"gọi món","example":"My friend orders a sandwich for lunch."},{"word":"delicious","ipa":"/dɪˈlɪʃəs/","pos":"adjective","meaning_vi":"ngon","example":"Your noodle soup is delicious."},{"word":"pay","ipa":"/peɪ/","pos":"verb","meaning_vi":"trả tiền","example":"I pay with cash today."},{"word":"bill","ipa":"/bɪl/","pos":"noun","meaning_vi":"hóa đơn","example":"Can we have the bill, please?"}],"questions":[{"question":"Where are Minh and Anna?","options":["In a café in Hanoi","In a restaurant in Hoi An","At home","In a café in Da Nang"],"answer_index":3,"explanation_vi":"Minh và Anna đang ở một quán cà phê tại Da Nang."},{"question":"What does Anna want to drink?","options":["Coffee with milk","A cup of tea","Orange juice","Water"],"answer_index":1,"explanation_vi":"Anna xin một tách trà."},{"question":"What does Minh order to eat?","options":["A sandwich","Ice cream","A chocolate cake","Noodle soup"],"answer_index":2,"explanation_vi":"Minh gọi thêm một chiếc bánh sô-cô-la."},{"question":"Where do they pay?","options":["At the counter","At the table","At the door","On the phone"],"answer_index":0,"explanation_vi":"Họ trả tiền ở quầy."}]}', 'course', 1, 'a1-at-the-cafe', 'food', 4)
