INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'A Small House with a Cat', 'My home', 'A1', '{"title":"A Small House with a Cat","summary_vi":"Bạn sẽ luyện miêu tả ngôi nhà và các phòng trong nhà.","sentences":["I live in a small house.","It has two bedrooms and one bathroom.","My favorite room is the kitchen.","There is a big table in the kitchen.","In the living room, there is a sofa.","My cat sleeps on the sofa all day.","Behind the house, there is a little garden.","I love my home."],"vocabulary":[{"word":"house","ipa":"/haʊs/","pos":"noun","meaning_vi":"ngôi nhà","example":"Their house has a red door."},{"word":"bedrooms","ipa":"/ˈbedruːmz/","pos":"noun","meaning_vi":"các phòng ngủ","example":"The flat has three bedrooms."},{"word":"bathroom","ipa":"/ˈbæθruːm/","pos":"noun","meaning_vi":"phòng tắm","example":"The bathroom is next to my room."},{"word":"favorite","ipa":"/ˈfeɪvərɪt/","pos":"adjective","meaning_vi":"yêu thích","example":"Blue is my favorite color."},{"word":"kitchen","ipa":"/ˈkɪtʃən/","pos":"noun","meaning_vi":"nhà bếp","example":"Mom cooks rice in the kitchen."},{"word":"living room","ipa":"/ˈlɪvɪŋ ruːm/","pos":"noun","meaning_vi":"phòng khách","example":"We watch TV in the living room."},{"word":"sofa","ipa":"/ˈsoʊfə/","pos":"noun","meaning_vi":"ghế sô-pha","example":"The new sofa is very soft."},{"word":"garden","ipa":"/ˈɡɑːrdn/","pos":"noun","meaning_vi":"khu vườn","example":"She grows flowers in her garden."}],"questions":[{"question":"How many bedrooms does the house have?","options":["One","Three","Two","Four"],"answer_index":2,"explanation_vi":"Ngôi nhà có hai phòng ngủ và một phòng tắm."},{"question":"What is the speaker''s favorite room?","options":["The bathroom","The kitchen","The bedroom","The living room"],"answer_index":1,"explanation_vi":"Phòng yêu thích của người nói là nhà bếp."},{"question":"Where does the cat sleep?","options":["On the sofa","In the garden","On the kitchen table","In the bathroom"],"answer_index":0,"explanation_vi":"Con mèo ngủ trên ghế sô-pha cả ngày."},{"question":"What is behind the house?","options":["A shop","A school","A road","A little garden"],"answer_index":3,"explanation_vi":"Phía sau nhà có một khu vườn nhỏ."}]}', 'course', 1, 'a1-my-home', 'daily', 5)
