INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Emma Is Lost', 'Asking for directions', 'A1', '{"title":"Emma Is Lost","summary_vi":"Bạn sẽ luyện hỏi đường và hiểu các chỉ dẫn đơn giản như rẽ trái, rẽ phải.","sentences":["Emma is lost in Hanoi.","She asks a man for help.","The man says to go straight.","Then turn left at the bank.","The post office is next to the bank.","After that, turn right at the school.","The lake is near the school.","Emma says thank you and smiles."],"vocabulary":[{"word":"lost","ipa":"/lɔːst/","pos":"adjective","meaning_vi":"bị lạc","example":"I am lost in this big city."},{"word":"straight","ipa":"/streɪt/","pos":"adverb","meaning_vi":"thẳng","example":"Go straight for five minutes."},{"word":"turn left","ipa":"/tɜːrn left/","pos":"phrase","meaning_vi":"rẽ trái","example":"Please turn left at the corner."},{"word":"turn right","ipa":"/tɜːrn raɪt/","pos":"phrase","meaning_vi":"rẽ phải","example":"You turn right after the market."},{"word":"bank","ipa":"/bæŋk/","pos":"noun","meaning_vi":"ngân hàng","example":"The bank opens at eight."},{"word":"post office","ipa":"/ˈpoʊst ˌɔːfɪs/","pos":"noun","meaning_vi":"bưu điện","example":"I send a letter at the post office."},{"word":"next to","ipa":"/nekst tuː/","pos":"phrase","meaning_vi":"bên cạnh","example":"The cafe is next to the library."},{"word":"near","ipa":"/nɪr/","pos":"preposition","meaning_vi":"gần","example":"My house is near the station."}],"questions":[{"question":"Where is Emma?","options":["In Hanoi","In Da Nang","In Hoi An","In New York"],"answer_index":0,"explanation_vi":"Emma bị lạc ở Hanoi."},{"question":"Where does Emma turn left?","options":["At the school","At the lake","At the bank","At the post office"],"answer_index":2,"explanation_vi":"Người đàn ông bảo rẽ trái ở ngân hàng."},{"question":"What is next to the bank?","options":["The school","The lake","A cafe","The post office"],"answer_index":3,"explanation_vi":"Bưu điện nằm cạnh ngân hàng."},{"question":"What is near the school?","options":["A market","The lake","A park","The station"],"answer_index":1,"explanation_vi":"Hồ nằm gần trường học."}]}', 'course', 1, 'a1-directions', 'travel', 7)
