INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Football and Grandma''s Soup', 'My weekend', 'A1', '{"title":"Football and Grandma''s Soup","summary_vi":"Bạn sẽ luyện kể về những hoạt động vui vẻ vào cuối tuần.","sentences":["On Saturday, I sleep late.","Then I play football with my friends.","In the afternoon, we eat ice cream.","On Sunday, I visit my grandmother.","She cooks my favorite soup.","After lunch, we watch a movie together.","I really love the weekend."],"vocabulary":[{"word":"Saturday","ipa":"/ˈsætərdeɪ/","pos":"noun","meaning_vi":"thứ Bảy","example":"We go to the zoo on Saturday."},{"word":"sleep late","ipa":"/sliːp leɪt/","pos":"phrase","meaning_vi":"ngủ muộn","example":"My dad likes to sleep late on Sunday."},{"word":"football","ipa":"/ˈfʊtbɔːl/","pos":"noun","meaning_vi":"bóng đá","example":"Football is popular in Vietnam."},{"word":"ice cream","ipa":"/ˈaɪs kriːm/","pos":"noun","meaning_vi":"kem","example":"I want chocolate ice cream."},{"word":"visit","ipa":"/ˈvɪzɪt/","pos":"verb","meaning_vi":"thăm","example":"We visit our cousins in July."},{"word":"grandmother","ipa":"/ˈɡrænmʌðər/","pos":"noun","meaning_vi":"bà","example":"My grandmother lives in the countryside."},{"word":"movie","ipa":"/ˈmuːvi/","pos":"noun","meaning_vi":"bộ phim","example":"That movie is very funny."},{"word":"weekend","ipa":"/ˈwiːkend/","pos":"noun","meaning_vi":"cuối tuần","example":"Do you work at the weekend?"}],"questions":[{"question":"What does the speaker do on Saturday morning?","options":["Plays football","Visits grandmother","Sleeps late","Watches a movie"],"answer_index":2,"explanation_vi":"Sáng thứ Bảy người nói ngủ muộn."},{"question":"What do they eat in the afternoon?","options":["Soup","Ice cream","Cake","Fruit"],"answer_index":1,"explanation_vi":"Buổi chiều họ ăn kem."},{"question":"Who does the speaker visit on Sunday?","options":["His grandmother","His teacher","His uncle","His friends"],"answer_index":0,"explanation_vi":"Chủ nhật người nói thăm bà."},{"question":"What do they do after lunch?","options":["Play football","Cook soup","Go to the beach","Watch a movie"],"answer_index":3,"explanation_vi":"Sau bữa trưa họ cùng xem phim."}]}', 'course', 1, 'a1-weekend', 'fun', 8)
