INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Room Key Please', 'Checking in at a hotel', 'A2', '{"title":"Room Key Please","summary_vi":"Bạn sẽ luyện cách làm thủ tục nhận phòng khách sạn qua một tin nhắn gửi bạn.","sentences":["Hi Anna, I arrived in Da Lat this afternoon!","The hotel is lovely, and it is only five minutes from the market.","At the front desk, a friendly woman checked my reservation.","She asked for my passport and gave me a room key.","My room is on the third floor, and it has a big window.","Breakfast is included, and it starts at seven o''clock.","I asked about the Wi-Fi, and she wrote the password on a card.","Tomorrow I am going to visit the flower gardens.","The weather is cooler than in Saigon, so I need my jacket.","Write back soon and tell me about your trip!"],"vocabulary":[{"word":"front desk","ipa":"/frʌnt desk/","pos":"noun","meaning_vi":"quầy lễ tân","example":"Please leave your key at the front desk."},{"word":"reservation","ipa":"/ˌrezərˈveɪʃən/","pos":"noun","meaning_vi":"việc đặt phòng","example":"I have a reservation for two nights."},{"word":"passport","ipa":"/ˈpæspɔːrt/","pos":"noun","meaning_vi":"hộ chiếu","example":"Don''t forget your passport at the airport."},{"word":"floor","ipa":"/flɔːr/","pos":"noun","meaning_vi":"tầng","example":"The lift stops on every floor."},{"word":"included","ipa":"/ɪnˈkluːdɪd/","pos":"adjective","meaning_vi":"đã bao gồm","example":"Dinner is included in the price."},{"word":"password","ipa":"/ˈpæswɜːrd/","pos":"noun","meaning_vi":"mật khẩu","example":"I forgot the password for my email."},{"word":"jacket","ipa":"/ˈdʒækɪt/","pos":"noun","meaning_vi":"áo khoác","example":"Take a jacket because it may rain."}],"questions":[{"question":"Where is the writer?","options":["Saigon","Hanoi","Da Lat","Anna''s house"],"answer_index":2,"explanation_vi":"Người viết vừa đến Đà Lạt chiều nay."},{"question":"What did the woman at the front desk ask for?","options":["A credit card","A passport","A phone number","A photo"],"answer_index":1,"explanation_vi":"Cô ấy yêu cầu xem hộ chiếu."},{"question":"Is breakfast free?","options":["No, it costs extra","Only on Sundays","It is not served","Yes, it is included"],"answer_index":3,"explanation_vi":"Bữa sáng đã được bao gồm trong giá phòng."},{"question":"What is the writer going to do tomorrow?","options":["Visit the flower gardens","Go back to Saigon","Meet Anna","Buy a jacket"],"answer_index":0,"explanation_vi":"Ngày mai người viết sẽ đi thăm vườn hoa."}]}', 'course', 1, 'a2-hotel', 'travel', 10)
