  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Feeling Under the Weather', 'Visiting the doctor', 'A2', '{"title":"Feeling Under the Weather","summary_vi":"Bạn sẽ luyện cách mô tả triệu chứng và hiểu lời dặn của bác sĩ qua một trang nhật ký.","sentences":["Dear diary, today I felt terrible, so I visited the doctor.","I had a sore throat and a headache since Monday.","The doctor asked me some questions and checked my temperature.","\"You have a fever, but it is not serious,\" she said.","She told me to rest at home and drink lots of water.","I also got some medicine from the pharmacy next door.","I should take it twice a day after meals.","The doctor said I should not go to school for two days.","I feel a little better now, so I am going to sleep early."],"vocabulary":[{"word":"sore throat","ipa":"/sɔːr θroʊt/","pos":"noun","meaning_vi":"đau họng","example":"Hot tea helps when you have a sore throat."},{"word":"headache","ipa":"/ˈhedeɪk/","pos":"noun","meaning_vi":"đau đầu","example":"Loud music gives me a headache."},{"word":"temperature","ipa":"/ˈtemprətʃər/","pos":"noun","meaning_vi":"nhiệt độ cơ thể","example":"The nurse took my temperature this morning."},{"word":"fever","ipa":"/ˈfiːvər/","pos":"noun","meaning_vi":"sốt","example":"The little boy has a high fever."},{"word":"rest","ipa":"/rest/","pos":"verb","meaning_vi":"nghỉ ngơi","example":"You should rest after the long trip."},{"word":"medicine","ipa":"/ˈmedɪsɪn/","pos":"noun","meaning_vi":"thuốc","example":"Take this medicine after lunch."},{"word":"pharmacy","ipa":"/ˈfɑːrməsi/","pos":"noun","meaning_vi":"hiệu thuốc","example":"The pharmacy closes at nine o''clock."}],"questions":[{"question":"Which problem did the writer have?","options":["A broken arm","A sore throat and a headache","A stomach ache","A sore back"],"answer_index":1,"explanation_vi":"Người viết bị đau họng và đau đầu."},{"question":"What did the doctor say about the fever?","options":["It was very dangerous","It would last a month","It was gone","It was not serious"],"answer_index":3,"explanation_vi":"Bác sĩ nói sốt không nghiêm trọng."},{"question":"Where did the writer buy the medicine?","options":["At a pharmacy next door","At a supermarket","At the hospital shop","Online"],"answer_index":0,"explanation_vi":"Thuốc mua ở hiệu thuốc bên cạnh."},{"question":"How long should the writer stay away from school?","options":["One day","A week","Two days","Three days"],"answer_index":2,"explanation_vi":"Bác sĩ dặn nghỉ học hai ngày."}]}', 'course', 1, 'a2-doctor', 'health', 11)
