INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Friends Forever', 'My best friend', 'A2', '{"title":"Friends Forever","summary_vi":"Bạn sẽ luyện cách giới thiệu và miêu tả người bạn thân nhất của mình.","sentences":["My best friend is called Tuan, and we met ten years ago.","We lived on the same street in Saigon.","Tuan is taller than me, and he is much funnier.","He always makes me laugh, even on bad days.","We both love football, so we play every Saturday morning.","Last month, I lost my phone, and Tuan helped me look for it.","He is also a very good listener.","When I have a problem, he gives me honest advice.","I am lucky to have a friend like him."],"vocabulary":[{"word":"best friend","ipa":"/best frend/","pos":"noun","meaning_vi":"bạn thân nhất","example":"My best friend lives next door."},{"word":"funnier","ipa":"/ˈfʌniər/","pos":"adjective","meaning_vi":"hài hước hơn","example":"This film is funnier than the last one."},{"word":"laugh","ipa":"/læf/","pos":"verb","meaning_vi":"cười","example":"We laugh a lot when we are together."},{"word":"listener","ipa":"/ˈlɪsənər/","pos":"noun","meaning_vi":"người biết lắng nghe","example":"A good teacher is also a good listener."},{"word":"problem","ipa":"/ˈprɑːbləm/","pos":"noun","meaning_vi":"vấn đề","example":"I have a problem with my laptop."},{"word":"honest","ipa":"/ˈɑːnɪst/","pos":"adjective","meaning_vi":"thành thật","example":"Please be honest and tell me the truth."},{"word":"lucky","ipa":"/ˈlʌki/","pos":"adjective","meaning_vi":"may mắn","example":"She was lucky to find a seat on the train."}],"questions":[{"question":"How long have they known each other?","options":["Two years","Five years","Twenty years","Ten years"],"answer_index":3,"explanation_vi":"Họ gặp nhau cách đây mười năm."},{"question":"What do they do on Saturday mornings?","options":["Play football","Go shopping","Watch films","Study English"],"answer_index":0,"explanation_vi":"Họ chơi bóng đá mỗi sáng thứ Bảy."},{"question":"How did Tuan help last month?","options":["He lent some money","He cooked dinner","He helped look for a lost phone","He fixed a bike"],"answer_index":2,"explanation_vi":"Tuan giúp tìm chiếc điện thoại bị mất."},{"question":"What does Tuan give when his friend has a problem?","options":["Some money","Honest advice","A present","A phone call"],"answer_index":1,"explanation_vi":"Tuấn cho lời khuyên chân thành."}]}', 'course', 1, 'a2-best-friend', 'people', 12)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Bus Number 18', 'Taking the bus across town', 'A2', '{"title":"Bus Number 18","summary_vi":"Bạn sẽ luyện từ vựng và câu hỏi khi đi xe buýt trong thành phố.","sentences":["Emma was visiting Saigon, and she wanted to see the zoo.","A local girl told her to take bus number 18.","Emma walked to the bus stop and waited for ten minutes.","The bus was crowded, but a young man gave her his seat.","She bought a ticket from the driver for seven thousand dong.","The ride was slower than a taxi, but it was much cheaper.","Emma watched the busy streets and the motorbikes through the window.","\"Which stop is the zoo?\" she asked the driver.","He smiled and said, \"The next one. I will tell you.\"","Emma got off the bus and thanked him."],"vocabulary":[{"word":"bus stop","ipa":"/bʌs stɑːp/","pos":"noun","meaning_vi":"trạm xe buýt","example":"The bus stop is near my school."},{"word":"crowded","ipa":"/ˈkraʊdɪd/","pos":"adjective","meaning_vi":"đông đúc","example":"The market is crowded on weekends."},{"word":"seat","ipa":"/siːt/","pos":"noun","meaning_vi":"chỗ ngồi","example":"Is this seat free?"},{"word":"ticket","ipa":"/ˈtɪkɪt/","pos":"noun","meaning_vi":"vé","example":"I lost my ticket on the way home."},{"word":"driver","ipa":"/ˈdraɪvər/","pos":"noun","meaning_vi":"tài xế","example":"The driver stopped for an old man."},{"word":"cheaper","ipa":"/ˈtʃiːpər/","pos":"adjective","meaning_vi":"rẻ hơn","example":"Rice is cheaper in the countryside."},{"word":"got off","ipa":"/ɡɑːt ɔːf/","pos":"phrase","meaning_vi":"xuống (xe)","example":"We got off the train at Hue."}],"questions":[{"question":"Where did Emma want to go?","options":["The market","The zoo","The airport","A museum"],"answer_index":1,"explanation_vi":"Emma muốn đi xem sở thú."},{"question":"Why did a man give Emma his seat?","options":["The bus was crowded","He was getting off","He knew her","She was tired"],"answer_index":0,"explanation_vi":"Xe đông nên chàng trai nhường ghế cho cô."},{"question":"Why did Emma choose the bus instead of a taxi?","options":["It was faster","It was cleaner","It was much cheaper","It was closer"],"answer_index":2,"explanation_vi":"Xe buýt chậm hơn taxi nhưng rẻ hơn nhiều."},{"question":"What did the driver promise?","options":["A free ticket","A map of the city","A taxi","To tell her the right stop"],"answer_index":3,"explanation_vi":"Tài xế hứa sẽ báo cho cô biết trạm cần xuống."}]}', 'course', 1, 'a2-bus-ride', 'travel', 13)
