  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Surprise!', 'A surprise birthday party', 'A2', '{"title":"Surprise!","summary_vi":"Bạn sẽ luyện kể lại một bữa tiệc sinh nhật bất ngờ bằng thì quá khứ đơn.","sentences":["Linh''s birthday was on Saturday, but she thought everyone forgot.","Her friends planned a surprise party at Minh''s house.","Minh told Linh that he needed help with his homework.","When she arrived, the lights were off, and the house was quiet.","Suddenly, everyone jumped out and shouted, \"Surprise!\"","Linh was so shocked that she almost dropped her bag.","Her friends decorated the room with balloons and colourful paper.","Tuan brought a big chocolate cake with twenty candles.","Linh made a wish and blew out all the candles.","It was the best birthday she ever had."],"vocabulary":[{"word":"surprise","ipa":"/sərˈpraɪz/","pos":"noun","meaning_vi":"sự bất ngờ","example":"The gift was a big surprise."},{"word":"party","ipa":"/ˈpɑːrti/","pos":"noun","meaning_vi":"bữa tiệc","example":"We are having a party on Friday night."},{"word":"shocked","ipa":"/ʃɑːkt/","pos":"adjective","meaning_vi":"sốc, rất ngạc nhiên","example":"He looked shocked when he heard the news."},{"word":"decorated","ipa":"/ˈdekəreɪtɪd/","pos":"verb","meaning_vi":"trang trí","example":"She decorated the cake with strawberries."},{"word":"balloons","ipa":"/bəˈluːnz/","pos":"noun","meaning_vi":"bóng bay","example":"The children love the red balloons."},{"word":"candles","ipa":"/ˈkændəlz/","pos":"noun","meaning_vi":"nến","example":"Please light the candles on the cake."},{"word":"wish","ipa":"/wɪʃ/","pos":"noun","meaning_vi":"điều ước","example":"Close your eyes and make a wish."}],"questions":[{"question":"What did Linh think on her birthday?","options":["Her friends were busy","Her friends forgot it","Her family was away","It was a normal day"],"answer_index":1,"explanation_vi":"Linh nghĩ mọi người đã quên sinh nhật mình."},{"question":"Why did Minh ask Linh to come to his house?","options":["To watch a film","To eat dinner","To get a gift","He said he needed homework help"],"answer_index":3,"explanation_vi":"Minh nói dối là cần giúp làm bài tập."},{"question":"How did Linh feel when everyone shouted?","options":["Angry","Bored","Shocked","Sleepy"],"answer_index":2,"explanation_vi":"Linh sốc đến mức suýt làm rơi túi."},{"question":"Who brought the cake?","options":["Tuan","Minh","Linh''s mother","A waiter"],"answer_index":0,"explanation_vi":"Tuấn mang chiếc bánh sô-cô-la đến."}]}', 'course', 1, 'a2-birthday', 'fun', 14)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'My First Coffee Shift', 'My first part-time job', 'A2', '{"title":"My First Coffee Shift","summary_vi":"Bạn sẽ luyện cách kể về công việc làm thêm đầu tiên và cảm xúc của mình.","sentences":["Last summer, I got my first part-time job at a café in Hanoi.","I worked there three afternoons a week.","At first, I was nervous, and I made many mistakes.","I forgot orders, and once I spilled coffee on a customer.","My manager, Mr. Hung, was patient and kind.","He showed me how to use the coffee machine.","After a month, I felt more confident.","I earned a small salary, and I saved half of it.","I learned to manage my time and talk to people.","Now I want to work there again next summer."],"vocabulary":[{"word":"part-time","ipa":"/ˌpɑːrt ˈtaɪm/","pos":"adjective","meaning_vi":"bán thời gian","example":"She has a part-time job at a bookshop."},{"word":"nervous","ipa":"/ˈnɜːrvəs/","pos":"adjective","meaning_vi":"lo lắng","example":"I feel nervous before every exam."},{"word":"customer","ipa":"/ˈkʌstəmər/","pos":"noun","meaning_vi":"khách hàng","example":"The customer wants a bigger size."},{"word":"manager","ipa":"/ˈmænɪdʒər/","pos":"noun","meaning_vi":"quản lý","example":"Our manager starts work at eight."},{"word":"patient","ipa":"/ˈpeɪʃənt/","pos":"adjective","meaning_vi":"kiên nhẫn","example":"Be patient with young children."},{"word":"confident","ipa":"/ˈkɑːnfɪdənt/","pos":"adjective","meaning_vi":"tự tin","example":"He is confident about his English now."},{"word":"salary","ipa":"/ˈsæləri/","pos":"noun","meaning_vi":"lương","example":"My brother gets his salary on the first day of the month."}],"questions":[{"question":"Where did the writer work?","options":["In a shop","In a school","At a café","In a hotel"],"answer_index":2,"explanation_vi":"Người viết làm việc ở một quán cà phê tại Hà Nội."},{"question":"What mistake did the writer make?","options":["Lost the keys","Spilled coffee on a customer","Broke the machine","Came late every day"],"answer_index":1,"explanation_vi":"Người viết làm đổ cà phê lên một khách hàng."},{"question":"What was Mr. Hung like?","options":["Patient and kind","Strict and angry","Quiet and shy","Busy and rude"],"answer_index":0,"explanation_vi":"Ông Hùng kiên nhẫn và tốt bụng."},{"question":"What did the writer do with the salary?","options":["Bought a phone","Gave it to a friend","Spent all of it","Saved half of it"],"answer_index":3,"explanation_vi":"Người viết tiết kiệm một nửa số lương."}]}', 'course', 1, 'a2-first-job', 'work', 15)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Pho From Scratch', 'Cooking pho at home', 'A2', '{"title":"Pho From Scratch","summary_vi":"Bạn sẽ luyện nghe và làm theo các bước nấu phở tại nhà bằng tiếng Anh.","sentences":["Today I am going to show you how to cook pho at home.","First, boil beef bones in a big pot for ten minutes.","Then wash the bones and add fresh water.","Put in an onion, some ginger and a few spices.","Let the soup cook slowly for at least four hours.","While you wait, slice the beef very thin.","Cook the rice noodles in hot water for one minute.","Put the noodles in a bowl and add the raw beef.","Pour the hot broth over everything, and the beef will cook.","Finally, add fresh herbs and a little lime juice."],"vocabulary":[{"word":"boil","ipa":"/bɔɪl/","pos":"verb","meaning_vi":"đun sôi, luộc","example":"Please boil the eggs for eight minutes."},{"word":"bones","ipa":"/boʊnz/","pos":"noun","meaning_vi":"xương","example":"The dog is chewing on some bones."},{"word":"ginger","ipa":"/ˈdʒɪndʒər/","pos":"noun","meaning_vi":"gừng","example":"Ginger tea is good for a cold."},{"word":"slice","ipa":"/slaɪs/","pos":"verb","meaning_vi":"thái lát","example":"Can you slice the tomatoes for the salad?"},{"word":"noodles","ipa":"/ˈnuːdəlz/","pos":"noun","meaning_vi":"mì, bún, bánh phở","example":"I eat noodles for lunch every Monday."},{"word":"broth","ipa":"/brɔːθ/","pos":"noun","meaning_vi":"nước dùng","example":"The chicken broth smells wonderful."},{"word":"herbs","ipa":"/ɜːrbz/","pos":"noun","meaning_vi":"rau thơm","example":"My grandmother grows herbs in small pots."}],"questions":[{"question":"Why do you boil the bones first?","options":["To make them soft","To cook the noodles","To start cleaning them","To add salt"],"answer_index":2,"explanation_vi":"Luộc xương trước rồi rửa sạch để nước dùng trong hơn."},{"question":"How long should the soup cook?","options":["Ten minutes","At least four hours","One hour","All night"],"answer_index":1,"explanation_vi":"Nước dùng phải nấu ít nhất bốn giờ."},{"question":"How is the beef cooked in this recipe?","options":["Fried in a pan","Grilled on a fire","Boiled with the bones","By the hot broth"],"answer_index":3,"explanation_vi":"Thịt bò sống được chín nhờ nước dùng nóng chan lên."},{"question":"What do you add at the end?","options":["Fresh herbs and lime juice","Sugar and milk","More bones","Fried onions"],"answer_index":0,"explanation_vi":"Cuối cùng thêm rau thơm tươi và chút nước chanh."}]}', 'course', 1, 'a2-cooking-pho', 'food', 16)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Nailing the Interview', 'Job interview tips', 'B1', '{"title":"Nailing the Interview","summary_vi":"Luyện nghe và nói về những mẹo chuẩn bị cho một buổi phỏng vấn xin việc.","sentences":["Last month I had my first job interview in two years, and I was terrified.","My friend Minh, who works in HR in Saigon, gave me some useful advice.","First, he told me to do some research on the company before the day.","If you know what the company does, you can ask smarter questions.","Second, practise answering common questions out loud instead of just thinking about them.","On the day, I arrived ten minutes early and tried to stay calm.","When the manager asked about my weaknesses, I was honest and explained how I am working on them.","I also gave specific examples, because they make your answers more convincing.","At the end, I asked about the team and the chances to grow.","Two days later, they called to offer me the job.","I have learned that being prepared matters more than being perfect."],"vocabulary":[{"word":"do some research","ipa":"/duː sʌm ˈriːsɜːrtʃ/","pos":"phrase","meaning_vi":"tìm hiểu, nghiên cứu","example":"Before you buy a laptop, you should do some research online."},{"word":"stay calm","ipa":"/steɪ kɑːm/","pos":"phrase","meaning_vi":"giữ bình tĩnh","example":"It is hard to stay calm when you are late for an exam."},{"word":"weaknesses","ipa":"/ˈwiːknəsɪz/","pos":"noun","meaning_vi":"điểm yếu","example":"Everyone has strengths and weaknesses, and that is normal."},{"word":"specific examples","ipa":"/spəˈsɪfɪk ɪɡˈzæmpəlz/","pos":"noun phrase","meaning_vi":"ví dụ cụ thể","example":"The teacher asked us to give specific examples in our essays."},{"word":"convincing","ipa":"/kənˈvɪnsɪŋ/","pos":"adjective","meaning_vi":"thuyết phục","example":"Her explanation was so convincing that I changed my mind."},{"word":"being prepared","ipa":"/ˈbiːɪŋ prɪˈperd/","pos":"phrase","meaning_vi":"việc chuẩn bị sẵn sàng","example":"Being prepared will help you feel more confident on stage."}],"questions":[{"question":"Who gave the writer advice about interviews?","options":["A manager at the company","Minh, a friend who works in HR","The writer''s teacher","A family member in Hanoi"],"answer_index":1,"explanation_vi":"Bài viết nói bạn Minh làm nhân sự ở Sài Gòn đã cho lời khuyên."},{"question":"What did the writer do on the day of the interview?","options":["Arrived late but calm","Brought a long written speech","Arrived ten minutes early and stayed calm","Asked for a higher salary"],"answer_index":2,"explanation_vi":"Người viết đến sớm mười phút và cố giữ bình tĩnh."},{"question":"Why did the writer give specific examples?","options":["They make answers more convincing","The manager demanded them","They shorten the interview","They hide weaknesses"],"answer_index":0,"explanation_vi":"Ví dụ cụ thể khiến câu trả lời thuyết phục hơn."},{"question":"What is the main message of the passage?","options":["Perfect answers are essential","Research is a waste of time","Interviews are always stressful","Being prepared matters more than being perfect"],"answer_index":3,"explanation_vi":"Câu cuối nhấn mạnh sự chuẩn bị quan trọng hơn sự hoàn hảo."}]}', 'course', 1, 'b1-job-interview', 'work', 17)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Screen Time Reset', 'Social media habits', 'B1', '{"title":"Screen Time Reset","summary_vi":"Luyện nghe và nói về thói quen dùng mạng xã hội và cách giảm thời gian dùng điện thoại.","sentences":["Hello everyone, and welcome back to the show.","Today I want to talk about how social media has changed my daily routine.","A year ago, I used to scroll through my phone for hours every night.","I kept checking likes, and I felt anxious whenever nobody replied to my posts.","Then my sister Linh challenged me to cut down on screen time for one week.","At first it was hard, because I reached for my phone out of habit.","By the third day, I had started reading books again before bed.","Now I only use social media for thirty minutes a day.","I have also turned off most notifications, which makes me feel much less distracted.","If you feel stressed online, try taking a short break and see what happens.","Thanks for listening, and see you next week."],"vocabulary":[{"word":"scroll through","ipa":"/skroʊl θruː/","pos":"phrasal verb","meaning_vi":"lướt xem","example":"I like to scroll through photos while I drink my coffee."},{"word":"anxious","ipa":"/ˈæŋkʃəs/","pos":"adjective","meaning_vi":"lo lắng","example":"He felt anxious before the final results came out."},{"word":"cut down on","ipa":"/kʌt daʊn ɑːn/","pos":"phrasal verb","meaning_vi":"giảm bớt","example":"My doctor told me to cut down on sugar."},{"word":"screen time","ipa":"/skriːn taɪm/","pos":"noun","meaning_vi":"thời gian nhìn màn hình","example":"Too much screen time can make your eyes tired."},{"word":"out of habit","ipa":"/aʊt əv ˈhæbɪt/","pos":"phrase","meaning_vi":"theo thói quen","example":"She locked the door out of habit, even in her own garden."},{"word":"notifications","ipa":"/ˌnoʊtɪfɪˈkeɪʃənz/","pos":"noun","meaning_vi":"thông báo","example":"I turn off notifications when I need to study."},{"word":"distracted","ipa":"/dɪˈstræktɪd/","pos":"adjective","meaning_vi":"bị xao nhãng","example":"The noise outside kept me distracted all afternoon."}],"questions":[{"question":"What did the speaker used to do every night?","options":["Write long blog posts","Watch films with Linh","Scroll through the phone for hours","Play online games"],"answer_index":2,"explanation_vi":"Người nói từng lướt điện thoại hàng giờ mỗi tối."},{"question":"Who challenged the speaker to reduce screen time?","options":["A doctor","The speaker''s sister, Linh","A teacher","A radio listener"],"answer_index":1,"explanation_vi":"Chị/em gái Linh đã thử thách người nói."},{"question":"What happened by the third day?","options":["The speaker quit social media","The speaker bought a new phone","The speaker felt very stressed","The speaker began reading books before bed"],"answer_index":3,"explanation_vi":"Đến ngày thứ ba, người nói đã đọc sách lại trước khi ngủ."},{"question":"What can we infer about the speaker now?","options":["They feel less distracted and calmer","They hate technology","They have deleted all accounts","They post more than before"],"answer_index":0,"explanation_vi":"Tắt thông báo giúp người nói ít bị xao nhãng hơn."}]}', 'course', 1, 'b1-social-media', 'tech', 18)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Tom''s Cheap Adventure', 'Travelling on a budget', 'B1', '{"title":"Tom''s Cheap Adventure","summary_vi":"Luyện nghe và đọc câu chuyện về chuyến du lịch Việt Nam tiết kiệm của một người bạn.","sentences":["Last summer, my friend Tom from Canada travelled around Vietnam on a tight budget.","He had saved up for six months, but he still had to be careful with money.","Instead of expensive hotels, he stayed in cheap hostels where he met other travellers.","In Hanoi, he joined a free walking tour and gave the guide a small tip.","He also learned that local buses are much cheaper than taxis.","When he got hungry, he ate where the locals ate, so every meal cost only a few dollars.","Tom booked his flights well in advance, which saved him a lot of money.","Of course, not everything went smoothly, because his bus broke down near Hue.","He waited for three hours, but he made friends with a family who shared their snacks.","By the end of the trip, he had spent less than he expected.","He says that travelling cheaply makes you more creative and more open to surprises."],"vocabulary":[{"word":"on a tight budget","ipa":"/ɑːn ə taɪt ˈbʌdʒɪt/","pos":"phrase","meaning_vi":"với ngân sách eo hẹp","example":"Many students live on a tight budget in big cities."},{"word":"saved up","ipa":"/seɪvd ʌp/","pos":"phrasal verb","meaning_vi":"để dành tiền","example":"She saved up enough money to buy a new bike."},{"word":"walking tour","ipa":"/ˈwɔːkɪŋ tʊr/","pos":"noun","meaning_vi":"tour đi bộ","example":"A walking tour is a great way to see the old streets."},{"word":"in advance","ipa":"/ɪn ədˈvæns/","pos":"phrase","meaning_vi":"trước, từ sớm","example":"You should reserve a table in advance on weekends."},{"word":"broke down","ipa":"/broʊk daʊn/","pos":"phrasal verb","meaning_vi":"bị hỏng","example":"Our car broke down on the highway last night."},{"word":"made friends with","ipa":"/meɪd frendz wɪð/","pos":"phrase","meaning_vi":"kết bạn với","example":"On the first day of school, he made friends with his neighbour."},{"word":"open to","ipa":"/ˈoʊpən tuː/","pos":"adjective phrase","meaning_vi":"sẵn sàng đón nhận","example":"Good managers are open to new ideas."}],"questions":[{"question":"How did Tom pay for his trip?","options":["His company paid for it","He borrowed from a friend","He won a prize","He had saved money for six months"],"answer_index":3,"explanation_vi":"Tom đã để dành tiền suốt sáu tháng."},{"question":"Why were his meals so cheap?","options":["He ate where local people ate","He cooked in the hostel","He skipped lunch","Hotels gave him free food"],"answer_index":0,"explanation_vi":"Anh ăn ở những quán người địa phương hay ăn."},{"question":"What went wrong near Hue?","options":["He lost his wallet","His bus broke down","His flight was cancelled","He missed the tour"],"answer_index":1,"explanation_vi":"Xe buýt của anh bị hỏng gần Huế."},{"question":"What does Tom think about cheap travel?","options":["It is boring and tiring","It is only for the young","It makes people more creative and open","It is too risky"],"answer_index":2,"explanation_vi":"Tom cho rằng đi tiết kiệm khiến ta sáng tạo và cởi mở hơn."}]}', 'course', 1, 'b1-budget-travel', 'travel', 19)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Finding Your Rhythm', 'Living in a big city', 'B1', '{"title":"Finding Your Rhythm","summary_vi":"Luyện nghe và nói về cách làm quen với cuộc sống ở một thành phố lớn.","sentences":["Moving to a big city can be exciting, but it takes time to get used to it.","When I first moved to Saigon, the traffic and the noise nearly drove me crazy.","My cousin Minh, who has lived here for ten years, gave me some advice.","He said I should find a quiet café or park where I can relax after work.","He also told me to learn the bus routes instead of relying on taxis.","Living in a city is expensive, so it helps to keep track of what you spend.","On the other hand, there are always things to do, from concerts to street markets.","If you feel lonely, join a club or a class to meet new people.","After six months, I have finally found my own rhythm.","I still miss my hometown, but I no longer want to leave."],"vocabulary":[{"word":"get used to","ipa":"/ɡet juːst tuː/","pos":"phrasal verb","meaning_vi":"làm quen với","example":"It took me a week to get used to the cold weather."},{"word":"drove me crazy","ipa":"/droʊv miː ˈkreɪzi/","pos":"phrase","meaning_vi":"làm tôi phát điên","example":"The loud music next door drove me crazy last night."},{"word":"relying on","ipa":"/rɪˈlaɪɪŋ ɑːn/","pos":"phrasal verb","meaning_vi":"dựa vào","example":"He is relying on his parents to pay for university."},{"word":"keep track of","ipa":"/kiːp træk əv/","pos":"phrase","meaning_vi":"theo dõi, ghi nhớ","example":"I use an app to keep track of my homework."},{"word":"on the other hand","ipa":"/ɑːn ðə ˈʌðər hænd/","pos":"phrase","meaning_vi":"mặt khác","example":"The flat is small. On the other hand, it is very cheap."},{"word":"rhythm","ipa":"/ˈrɪðəm/","pos":"noun","meaning_vi":"nhịp sống, nhịp điệu","example":"After the holiday, it was hard to get back into a work rhythm."}],"questions":[{"question":"What bothered the writer most at first in Saigon?","options":["The weather","The traffic and noise","The food","The neighbours"],"answer_index":1,"explanation_vi":"Giao thông và tiếng ồn suýt làm người viết phát điên."},{"question":"What advice did Minh give about transport?","options":["Buy a motorbike","Avoid going out","Rely on taxis","Learn the bus routes"],"answer_index":3,"explanation_vi":"Minh khuyên nên học các tuyến xe buýt thay vì dựa vào taxi."},{"question":"What should you do if you feel lonely?","options":["Join a club or a class","Move back home","Stay in a café","Call a taxi"],"answer_index":0,"explanation_vi":"Bài khuyên tham gia câu lạc bộ hoặc lớp học để gặp người mới."},{"question":"How does the writer feel after six months?","options":["Ready to leave the city","Angry about the cost","More settled, though still missing home","Bored with city events"],"answer_index":2,"explanation_vi":"Người viết đã quen nhịp sống nhưng vẫn nhớ quê."}]}', 'course', 1, 'b1-city-life', 'daily', 20)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Little by Little', 'Learning a new language', 'B1', '{"title":"Little by Little","summary_vi":"Luyện nghe và đọc về thói quen học ngoại ngữ mỗi ngày của một cô gái tên Linh.","sentences":["Linh has been learning English for three years, and her progress has surprised everyone.","She says the secret is to practise a little every day rather than a lot once a week.","Every morning, she listens to a short podcast while she walks to work.","Whenever she hears a new word, she writes it down and looks it up later.","She is not afraid of making mistakes, because she knows they help her learn.","Last year, she joined an online group where members chat with native speakers.","At first she felt shy, but her confidence has grown quickly.","If you want to speak fluently, you have to use the language in real situations.","Linh also watches films without subtitles to train her ears.","She believes that anyone can improve if they stay patient and keep going."],"vocabulary":[{"word":"rather than","ipa":"/ˈræðər ðæn/","pos":"phrase","meaning_vi":"hơn là, thay vì","example":"I prefer tea rather than coffee in the evening."},{"word":"writes it down","ipa":"/raɪts ɪt daʊn/","pos":"phrasal verb","meaning_vi":"ghi lại","example":"My brother always writes it down when he gets a good idea."},{"word":"looks it up","ipa":"/lʊks ɪt ʌp/","pos":"phrasal verb","meaning_vi":"tra cứu","example":"If she does not know a word, she looks it up in a dictionary."},{"word":"native speakers","ipa":"/ˈneɪtɪv ˈspiːkərz/","pos":"noun phrase","meaning_vi":"người bản ngữ","example":"Native speakers often talk very fast."},{"word":"confidence","ipa":"/ˈkɑːnfɪdəns/","pos":"noun","meaning_vi":"sự tự tin","example":"Practice gives you confidence before a big presentation."},{"word":"fluently","ipa":"/ˈfluːəntli/","pos":"adverb","meaning_vi":"trôi chảy","example":"After living abroad, he spoke Japanese fluently."},{"word":"keep going","ipa":"/kiːp ˈɡoʊɪŋ/","pos":"phrase","meaning_vi":"tiếp tục, không bỏ cuộc","example":"The hill is steep, but we have to keep going."}],"questions":[{"question":"What is Linh''s secret to improving?","options":["Studying only at weekends","Practising a little every day","Taking expensive classes","Moving abroad"],"answer_index":1,"explanation_vi":"Linh luyện một chút mỗi ngày thay vì nhiều lần một tuần."},{"question":"What does she do when she hears a new word?","options":["She ignores it","She asks her teacher","She writes it down and looks it up later","She translates the whole text"],"answer_index":2,"explanation_vi":"Cô ghi từ mới lại rồi tra sau."},{"question":"How did she feel when she joined the online group?","options":["Angry","Shy at first","Very confident","Bored"],"answer_index":1,"explanation_vi":"Ban đầu cô cảm thấy ngại ngùng."},{"question":"What is the main idea of the passage?","options":["Films are better than books","Mistakes should be avoided","Only native speakers can teach","Patience and daily practice lead to progress"],"answer_index":3,"explanation_vi":"Sự kiên nhẫn và luyện tập hằng ngày giúp tiến bộ."}]}', 'course', 1, 'b1-learning-languages', 'study', 21)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Small Changes, Big Impact', 'Cutting down on plastic', 'B1', '{"title":"Small Changes, Big Impact","summary_vi":"Luyện nghe và đọc về cách một người giảm dùng đồ nhựa trong cuộc sống hằng ngày.","sentences":["Sara lives in Melbourne, and last January she decided to cut down on plastic.","She started by counting how many plastic bags she threw away each week.","The number shocked her, so she bought a cloth bag and a reusable water bottle.","Now she refuses plastic straws and brings her own container when she buys takeaway.","At the market, she picks fruit and vegetables that are not wrapped in packaging.","It was not always easy, because many products come in plastic by default.","However, she has found shops that let customers refill bottles with soap and shampoo.","Her friends laughed at first, but several of them have now copied her habits.","Sara knows that one person cannot solve the problem alone.","Still, she believes small changes add up if enough people join in."],"vocabulary":[{"word":"cut down on","ipa":"/kʌt daʊn ɑːn/","pos":"phrasal verb","meaning_vi":"giảm bớt","example":"We are trying to cut down on energy use at home."},{"word":"threw away","ipa":"/θruː əˈweɪ/","pos":"phrasal verb","meaning_vi":"vứt đi","example":"He threw away his old shoes after the trip."},{"word":"reusable","ipa":"/riˈjuːzəbəl/","pos":"adjective","meaning_vi":"có thể dùng lại","example":"A reusable cup is better for the environment."},{"word":"packaging","ipa":"/ˈpækɪdʒɪŋ/","pos":"noun","meaning_vi":"bao bì","example":"The packaging was bigger than the gift itself."},{"word":"by default","ipa":"/baɪ dɪˈfɔːlt/","pos":"phrase","meaning_vi":"mặc định","example":"The phone sets the language to English by default."},{"word":"refill","ipa":"/riːˈfɪl/","pos":"verb","meaning_vi":"đổ đầy lại","example":"You can refill your bottle at the water station."},{"word":"add up","ipa":"/æd ʌp/","pos":"phrasal verb","meaning_vi":"cộng dồn lại","example":"Small savings add up over a year."},{"word":"join in","ipa":"/dʒɔɪn ɪn/","pos":"phrasal verb","meaning_vi":"tham gia cùng","example":"Everyone is welcome to join in the game."}],"questions":[{"question":"How did Sara begin her plastic-free journey?","options":["She joined a protest","She counted the plastic bags she threw away","She closed her kitchen","She moved to a village"],"answer_index":1,"explanation_vi":"Cô bắt đầu bằng việc đếm số túi nhựa vứt đi mỗi tuần."},{"question":"Why was it difficult for Sara?","options":["Shops are always closed","She could not afford a bag","Plastic is the default packaging for many products","Her friends stopped talking to her"],"answer_index":2,"explanation_vi":"Nhiều sản phẩm mặc định được đựng trong nhựa."},{"question":"What happened to Sara''s friends?","options":["Several of them copied her habits","They moved to another city","They criticised her online","They ignored the topic"],"answer_index":0,"explanation_vi":"Một số bạn đã bắt chước thói quen của cô."},{"question":"What does Sara believe?","options":["One person can fix everything","Plastic is not a problem","Only governments can help","Small changes matter when many people join in"],"answer_index":3,"explanation_vi":"Cô tin những thay đổi nhỏ cộng dồn khi nhiều người cùng làm."}]}', 'course', 1, 'b1-plastic-free', 'nature', 22)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Streetside Flavours', 'Street food culture in Vietnam', 'B1', '{"title":"Streetside Flavours","summary_vi":"Luyện nghe và nói về văn hóa ăn vặt vỉa hè đặc sắc ở Hà Nội và Huế.","sentences":["If you visit Vietnam, you should not miss the street food.","In Hanoi, many people start the day with a hot bowl of pho from a small stall.","In Hue, my grandmother''s favourite snack is banh beo, which is served in tiny dishes.","What makes street food special is that every vendor has a recipe passed down in the family.","Prices are low, so students and office workers eat there almost every day.","You usually sit on a plastic stool at the side of the road.","At first, some tourists worry about hygiene, but a busy stall is normally a good sign.","Locals say that if there is a long queue, the food must be fresh and tasty.","Many foreigners who have tried it say that they miss the flavours after going home.","Street food is more than a cheap meal, because it brings neighbours together."],"vocabulary":[{"word":"street food","ipa":"/striːt fuːd/","pos":"noun","meaning_vi":"đồ ăn đường phố","example":"Street food is cheap and delicious in many Asian cities."},{"word":"stall","ipa":"/stɔːl/","pos":"noun","meaning_vi":"quầy hàng, sạp","example":"She runs a fruit stall near the station."},{"word":"vendor","ipa":"/ˈvendər/","pos":"noun","meaning_vi":"người bán hàng rong","example":"The vendor sells hot corn every evening."},{"word":"passed down","ipa":"/pæst daʊn/","pos":"phrasal verb","meaning_vi":"truyền lại","example":"This song was passed down from my great-grandmother."},{"word":"hygiene","ipa":"/ˈhaɪdʒiːn/","pos":"noun","meaning_vi":"vệ sinh","example":"Good hygiene starts with washing your hands."},{"word":"queue","ipa":"/kjuː/","pos":"noun","meaning_vi":"hàng người xếp hàng","example":"There was a long queue outside the cinema."},{"word":"a good sign","ipa":"/ə ɡʊd saɪn/","pos":"phrase","meaning_vi":"dấu hiệu tốt","example":"Her smile was a good sign after the meeting."}],"questions":[{"question":"How is banh beo served in Hue?","options":["In big bowls","In tiny dishes","On banana leaves only","In plastic bags"],"answer_index":1,"explanation_vi":"Bánh bèo được dọn trong những đĩa nhỏ xíu."},{"question":"Why is street food special according to the passage?","options":["It is always the cheapest","It is only for tourists","Every vendor has a family recipe passed down","It is served in restaurants"],"answer_index":2,"explanation_vi":"Mỗi người bán có công thức gia truyền."},{"question":"What does a long queue usually mean?","options":["The food is fresh and tasty","The stall is closing","The prices are high","The service is slow"],"answer_index":0,"explanation_vi":"Hàng dài thường báo hiệu đồ ăn tươi ngon."},{"question":"What is the final message of the passage?","options":["Tourists should avoid stalls","Hygiene does not matter","Street food only suits students","Street food also brings people together"],"answer_index":3,"explanation_vi":"Đồ ăn vỉa hè không chỉ rẻ mà còn gắn kết hàng xóm."}]}', 'course', 1, 'b1-street-food', 'food', 23)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'The Home Office Balance', 'Working from home', 'B1', '{"title":"The Home Office Balance","summary_vi":"Luyện nghe và đọc về ưu nhược điểm của việc làm việc tại nhà và cách giữ cân bằng.","sentences":["Since the pandemic, millions of people have started working from home.","My colleague Emma in London has done it for three years now.","She loves skipping the long commute, which gives her an extra hour every morning.","However, she admits that it is hard to separate work from private life.","When her laptop is always on the kitchen table, she tends to answer emails late at night.","To fix this, she created a small workspace in the spare room and set fixed hours.","She also makes a point of going for a walk at lunchtime.","Emma sometimes feels lonely, so she meets her team at a café once a week.","If you work from home, communication becomes even more important.","Short video calls can prevent misunderstandings and help everyone feel connected.","In her opinion, the best solution is a mix of home and office days."],"vocabulary":[{"word":"working from home","ipa":"/ˈwɜːrkɪŋ frəm hoʊm/","pos":"phrase","meaning_vi":"làm việc tại nhà","example":"Working from home saves me time and money."},{"word":"commute","ipa":"/kəˈmjuːt/","pos":"noun","meaning_vi":"quãng đường đi làm","example":"My daily commute takes about forty minutes by train."},{"word":"separate","ipa":"/ˈsepəreɪt/","pos":"verb","meaning_vi":"tách biệt","example":"It is wise to separate your savings from your daily money."},{"word":"tends to","ipa":"/tendz tuː/","pos":"phrase","meaning_vi":"có xu hướng","example":"My brother tends to forget his keys."},{"word":"fixed hours","ipa":"/fɪkst ˈaʊərz/","pos":"noun phrase","meaning_vi":"giờ làm cố định","example":"The shop keeps fixed hours from nine to six."},{"word":"makes a point of","ipa":"/meɪks ə pɔɪnt əv/","pos":"phrase","meaning_vi":"luôn cố gắng làm gì","example":"She makes a point of calling her parents every Sunday."},{"word":"feel connected","ipa":"/fiːl kəˈnektɪd/","pos":"phrase","meaning_vi":"cảm thấy gắn kết","example":"Group chats help us feel connected when we live far apart."}],"questions":[{"question":"What does Emma like most about working from home?","options":["Cheaper rent","Skipping the long commute","Bigger salary","More meetings"],"answer_index":1,"explanation_vi":"Cô thích không phải đi làm xa và có thêm một giờ mỗi sáng."},{"question":"What problem does she admit having?","options":["Her internet is slow","Her boss is strict","It is hard to separate work from private life","She has no laptop"],"answer_index":2,"explanation_vi":"Cô khó tách biệt công việc và đời sống riêng."},{"question":"How does Emma deal with feeling lonely?","options":["She meets her team at a café weekly","She quits her job","She works at night","She avoids video calls"],"answer_index":0,"explanation_vi":"Cô gặp đồng nghiệp ở quán cà phê mỗi tuần một lần."},{"question":"What does Emma think is the best solution?","options":["Always staying at home","Always working in an office","Working only at night","A mix of home and office days"],"answer_index":3,"explanation_vi":"Theo cô, kết hợp ngày ở nhà và ngày ở văn phòng là tốt nhất."}]}', 'course', 1, 'b1-work-from-home', 'work', 24)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'My New Coworker Is a Bot', 'AI at work', 'B2', '{"title":"My New Coworker Is a Bot","summary_vi":"Luyện nghe và đọc một bài bình luận về việc trí tuệ nhân tạo thay đổi công việc văn phòng, cùng các cụm từ hay dùng khi nói về công nghệ.","sentences":["When my company introduced an AI assistant last spring, I was convinced it would take my job.","Instead, it took the most tedious parts of it, and I have been wrestling with mixed feelings ever since.","My name is Linh, and I manage a small marketing team in Da Nang.","Reports that once took a whole afternoon are now drafted in minutes, which has freed us up for more creative work.","Had I known how useful it would be, I would have asked for it years ago.","However, the tool is far from flawless, and its confident mistakes can slip under the radar.","Last month a client was almost sent a proposal containing statistics that the software had simply made up.","That is why every output must be double-checked by a human before it goes out.","Some colleagues worry that juniors will never learn the craft if machines do all the groundwork.","I see their point, but I think the real danger is complacency rather than the technology itself.","If we treat AI as a shortcut, we will lose our edge; as a sparring partner, we will sharpen it.","In the long run, the people who thrive will know when to trust the machine and when to overrule it."],"vocabulary":[{"word":"tedious","ipa":"/ˈtiːdiəs/","pos":"adjective","meaning_vi":"tẻ nhạt, nhàm chán","example":"Copying numbers from one spreadsheet to another is a tedious task."},{"word":"wrestling with","ipa":"/ˈrɛslɪŋ wɪð/","pos":"phrase","meaning_vi":"vật lộn với (vấn đề, cảm xúc)","example":"She has been wrestling with the decision to change careers."},{"word":"slip under the radar","ipa":"/slɪp ˈʌndər ðə ˈreɪdɑːr/","pos":"idiom","meaning_vi":"lọt qua mà không bị chú ý","example":"Small errors in the budget can easily slip under the radar."},{"word":"made up","ipa":"/meɪd ʌp/","pos":"phrasal verb","meaning_vi":"bịa ra","example":"He made up an excuse because he had forgotten the meeting."},{"word":"complacency","ipa":"/kəmˈpleɪsənsi/","pos":"noun","meaning_vi":"sự tự mãn, chủ quan","example":"Success often breeds complacency in large companies."},{"word":"lose our edge","ipa":"/luːz ˈaʊər ɛdʒ/","pos":"idiom","meaning_vi":"mất lợi thế cạnh tranh","example":"If we stop learning new skills, we will lose our edge in the market."},{"word":"sparring partner","ipa":"/ˈspɑːrɪŋ ˈpɑːrtnər/","pos":"noun","meaning_vi":"người cùng tranh luận, đối trọng giúp mình giỏi lên","example":"My brother is my favourite sparring partner when I rehearse debates."},{"word":"in the long run","ipa":"/ɪn ðə lɔːŋ rʌn/","pos":"idiom","meaning_vi":"về lâu dài","example":"Cheap tools can cost you more in the long run."}],"questions":[{"question":"How did the AI assistant change Linh''s work?","options":["It replaced her whole team","It took over the boring tasks and left time for creative work","It made reports take longer","It forced her to move to another city"],"answer_index":1,"explanation_vi":"Công cụ AI đảm nhận phần việc tẻ nhạt nên cả nhóm có thêm thời gian cho việc sáng tạo."},{"question":"Why must every output be double-checked by a human?","options":["The software is too slow","Clients dislike automated reports","The tool can state false information with confidence","Managers do not trust any technology"],"answer_index":2,"explanation_vi":"Phần mềm từng tự bịa ra số liệu mà vẫn tỏ ra rất chắc chắn."},{"question":"What does the writer see as the biggest danger?","options":["Becoming complacent about relying on AI","Machines becoming too intelligent","Juniors earning too much","Companies refusing to adopt new tools"],"answer_index":0,"explanation_vi":"Tác giả cho rằng mối nguy thật sự là sự chủ quan chứ không phải bản thân công nghệ."},{"question":"What can be inferred about the writer''s attitude to AI?","options":["Strongly opposed to it","Blindly enthusiastic","Cautiously positive","Completely indifferent"],"answer_index":2,"explanation_vi":"Bà ghi nhận lợi ích nhưng vẫn nhấn mạnh việc kiểm tra và dùng có chừng mực."}]}', 'course', 1, 'b2-ai-at-work', 'tech', 25)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'The Day My Brain Pulled the Plug', 'Burnout and mental health', 'B2', '{"title":"The Day My Brain Pulled the Plug","summary_vi":"Luyện đọc và nghe một bài tiểu luận cá nhân về kiệt sức do công việc, cùng các từ vựng nói về sức khỏe tinh thần.","sentences":["Two winters ago, I stopped being able to read my own emails.","The words were there, but my brain refused to hold them, as if someone had pulled the plug.","I was a software engineer in Ho Chi Minh City, and I had been running on empty for almost a year.","At the time, I called it tiredness and told myself that a long weekend would fix everything.","It was only when my sister noticed that I had stopped laughing that I finally saw a doctor.","Burnout, she explained, is not simply being overworked; it is chronic exhaustion mixed with cynicism and falling performance.","If I had taken the early warning signs seriously, I might not have lost three months to recovery.","Part of the problem was a culture that treats exhaustion as a badge of honour.","Staying late was praised, and taking a day off was quietly seen as a lack of commitment.","Recovery meant setting firm boundaries, such as switching off notifications after seven in the evening.","It also meant asking for help, which turned out to be harder than any coding problem.","Today I still care about my work, but I no longer let it define my worth."],"vocabulary":[{"word":"pulled the plug","ipa":"/pʊld ðə plʌɡ/","pos":"idiom","meaning_vi":"ngắt, dừng hẳn (như rút phích cắm)","example":"The investors pulled the plug on the project after two years."},{"word":"running on empty","ipa":"/ˈrʌnɪŋ ɑːn ˈɛmpti/","pos":"idiom","meaning_vi":"cạn kiệt năng lượng mà vẫn cố làm","example":"By the end of exam season, most students are running on empty."},{"word":"chronic","ipa":"/ˈkrɑːnɪk/","pos":"adjective","meaning_vi":"mãn tính, kéo dài","example":"Chronic stress can weaken your immune system."},{"word":"cynicism","ipa":"/ˈsɪnɪsɪzəm/","pos":"noun","meaning_vi":"thói hoài nghi, bi quan","example":"Years of broken promises had left him with a deep cynicism about politics."},{"word":"warning signs","ipa":"/ˈwɔːrnɪŋ saɪnz/","pos":"noun","meaning_vi":"dấu hiệu cảnh báo","example":"Constant headaches can be one of the warning signs of overwork."},{"word":"a badge of honour","ipa":"/ə bædʒ əv ˈɑːnər/","pos":"idiom","meaning_vi":"niềm tự hào, thứ để khoe","example":"For some people, sleeping only four hours is a badge of honour."},{"word":"firm boundaries","ipa":"/fɜːrm ˈbaʊndriz/","pos":"noun","meaning_vi":"ranh giới rõ ràng","example":"Parents who set firm boundaries usually raise more confident children."}],"questions":[{"question":"What was the first sign that something was wrong?","options":["He lost his job","He could no longer take in the words of his emails","He moved to another country","He stopped using his phone"],"answer_index":1,"explanation_vi":"Ông không thể đọc nổi email của chính mình vì não không tiếp nhận được chữ."},{"question":"According to the writer''s sister, burnout is","options":["the same as feeling tired","caused only by laziness","a short-term reaction to a bad week","a long-lasting state of exhaustion with other symptoms"],"answer_index":3,"explanation_vi":"Kiệt sức là sự mệt mỏi kéo dài kèm hoài nghi và hiệu suất giảm sút."},{"question":"What does the writer criticise about workplace culture?","options":["It praises people who exhaust themselves","It pays too little","It bans weekends","It offers too many holidays"],"answer_index":0,"explanation_vi":"Văn hóa công sở coi việc kiệt sức như một huy hiệu danh dự."},{"question":"What does the final sentence suggest?","options":["He has left his career for good","He now values himself beyond his job","He regrets asking for help","He works longer hours than before"],"answer_index":1,"explanation_vi":"Anh vẫn quan tâm công việc nhưng không còn lấy nó làm thước đo giá trị bản thân."}]}', 'course', 1, 'b2-burnout', 'health', 26)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Freedom on Two Wheels', 'The gig economy', 'B2', '{"title":"Freedom on Two Wheels","summary_vi":"Luyện nghe và đọc một bản tin chuyên đề về lao động tự do qua ứng dụng, với từ vựng về hợp đồng, thu nhập và quyền lợi.","sentences":["Every morning at six, Minh Tuan switches on his phone and waits for the first delivery request to arrive.","He is one of hundreds of thousands of ride-hailing and delivery drivers working in Vietnam''s big cities.","For many of them, gig work offers a flexibility that traditional jobs simply cannot match.","Drivers choose their own hours, and some earn more than they did in factories.","Yet this freedom comes at a price, since gig workers are classed as independent contractors rather than employees.","They receive no paid leave, no sick pay and, in many cases, no insurance unless they arrange it themselves.","Income can also be unpredictable, as the platforms adjust their commission rates with little warning.","\"One week I make a decent living, and the next I barely break even,\" Minh Tuan says.","Lawmakers in several countries are now debating whether these workers deserve a new legal category.","Supporters of the gig model argue that stricter rules would drive companies out and cost jobs.","Critics reply that a business built on workers'' insecurity is not sustainable in the long term.","Whatever the outcome, it is clear that the way we define work is being rewritten."],"vocabulary":[{"word":"comes at a price","ipa":"/kʌmz æt ə praɪs/","pos":"idiom","meaning_vi":"phải trả giá, có cái giá đi kèm","example":"Fast growth often comes at a price, usually in the form of stress."},{"word":"independent contractors","ipa":"/ˌɪndɪˈpɛndənt ˈkɑːntræktərz/","pos":"noun","meaning_vi":"người làm hợp đồng độc lập","example":"Many designers work as independent contractors for several clients."},{"word":"paid leave","ipa":"/peɪd liːv/","pos":"noun","meaning_vi":"nghỉ phép có lương","example":"New parents in some countries receive a year of paid leave."},{"word":"commission","ipa":"/kəˈmɪʃən/","pos":"noun","meaning_vi":"tiền hoa hồng","example":"The salesman earns a ten percent commission on every phone he sells."},{"word":"make a decent living","ipa":"/meɪk ə ˈdiːsənt ˈlɪvɪŋ/","pos":"phrase","meaning_vi":"kiếm đủ sống tử tế","example":"It is hard to make a decent living as a freelance musician."},{"word":"break even","ipa":"/breɪk ˈiːvən/","pos":"phrasal verb","meaning_vi":"hòa vốn","example":"The new café hopes to break even by the end of the year."},{"word":"sustainable","ipa":"/səˈsteɪnəbəl/","pos":"adjective","meaning_vi":"bền vững","example":"A sustainable business model does not depend on exhausting its workers."}],"questions":[{"question":"What attracts many people to gig work?","options":["Guaranteed pensions","The freedom to choose their hours","Free insurance","Fixed monthly salaries"],"answer_index":1,"explanation_vi":"Tài xế được tự chọn giờ làm, điều mà công việc truyền thống khó đáp ứng."},{"question":"Why can gig workers'' income be hard to predict?","options":["They are paid in foreign currency","Customers rarely order anything","Platforms may change their commission rates suddenly","They must pay for fuel in advance"],"answer_index":2,"explanation_vi":"Các nền tảng điều chỉnh mức hoa hồng mà ít khi báo trước."},{"question":"What is the main argument of supporters of the gig model?","options":["Strict rules could harm companies and reduce jobs","Drivers should be paid less","Insurance is unnecessary","Traditional jobs are better"],"answer_index":0,"explanation_vi":"Họ cho rằng luật chặt hơn có thể khiến công ty rút đi và mất việc làm."},{"question":"What is the tone of the final sentence?","options":["Humorous","Thoughtful about a broader change","Angry at the drivers","Certain about the result"],"answer_index":1,"explanation_vi":"Câu cuối nhận định rằng khái niệm về công việc đang được viết lại, không khẳng định kết quả."}]}', 'course', 1, 'b2-gig-economy', 'work', 27)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'A Ticket to Walk Down My Own Street', 'Tourism and local communities', 'B2', '{"title":"A Ticket to Walk Down My Own Street","summary_vi":"Luyện nghe và đọc một bản tin về du lịch quá tải và ảnh hưởng đến cộng đồng địa phương, cùng các cụm từ về du lịch có trách nhiệm.","sentences":["In the old quarter of Hoi An, residents now joke that they need a ticket to walk down their own street.","The town welcomed millions of visitors last year, far more than its narrow lanes were ever designed to handle.","Tourism has undoubtedly brought wealth, but it has also pushed up rents and driven out long-standing families.","Shops that once sold hardware and rice are being replaced by souvenir stalls and cafés aimed at foreigners.","The same story is told in Venice, Barcelona and Kyoto, where locals have staged protests against the crowds.","Some cities have responded by capping visitor numbers or charging an entrance fee on busy days.","Others encourage travellers to explore lesser-known districts, so that the pressure is spread more evenly.","Had authorities acted sooner, many communities might have avoided the resentment now spilling over.","Experts stress that tourists are not the enemy; it is unmanaged growth that does the damage.","Travellers can make a difference by staying in locally owned guesthouses and eating where residents eat.","They can also avoid peak season, when the strain on water and waste services is at its worst.","After all, a destination that loses its soul has little left to offer."],"vocabulary":[{"word":"pushed up","ipa":"/pʊʃt ʌp/","pos":"phrasal verb","meaning_vi":"đẩy (giá) lên","example":"The new airport pushed up property prices across the region."},{"word":"driven out","ipa":"/ˈdrɪvən aʊt/","pos":"phrasal verb","meaning_vi":"bị đuổi đi, buộc phải rời","example":"Small bakeries were driven out by the big supermarket chains."},{"word":"capping","ipa":"/ˈkæpɪŋ/","pos":"verb","meaning_vi":"đặt mức trần, giới hạn","example":"The council is considering capping the number of tour buses downtown."},{"word":"spilling over","ipa":"/ˈspɪlɪŋ ˈoʊvər/","pos":"phrasal verb","meaning_vi":"tràn ra, bùng phát","example":"The argument was spilling over into every family dinner."},{"word":"unmanaged","ipa":"/ʌnˈmænɪdʒd/","pos":"adjective","meaning_vi":"không được quản lý","example":"Unmanaged waste has turned the beach into a health hazard."},{"word":"make a difference","ipa":"/meɪk ə ˈdɪfrəns/","pos":"idiom","meaning_vi":"tạo ra khác biệt, có tác động","example":"Even small donations can make a difference to a village school."},{"word":"peak season","ipa":"/piːk ˈsiːzən/","pos":"noun","meaning_vi":"mùa cao điểm","example":"Hotel rooms are twice as expensive during peak season."}],"questions":[{"question":"What do Hoi An residents mean by their joke about a ticket?","options":["Streets are now privately owned","Crowds make it hard to move around their own neighbourhood","Local transport is free","Visitors must pay locals"],"answer_index":1,"explanation_vi":"Đó là cách nói đùa về việc phố cổ quá đông đến mức dân địa phương khó đi lại."},{"question":"What is one negative effect of tourism mentioned?","options":["Fewer foreign investors","Lower wages for guides","Cleaner rivers","Rising rents that push out long-term residents"],"answer_index":3,"explanation_vi":"Giá thuê nhà tăng khiến nhiều gia đình sống lâu năm phải rời đi."},{"question":"What do experts say about the cause of the damage?","options":["Tourists themselves are to blame","Growth that is not managed properly","Bad weather","Poor hotel service"],"answer_index":1,"explanation_vi":"Chuyên gia nhấn mạnh thủ phạm là sự tăng trưởng không được quản lý, không phải du khách."},{"question":"What can be inferred from the sentence beginning ''Had authorities acted sooner''?","options":["Authorities acted quickly enough","Tensions could have been reduced with earlier action","Residents want more tourists","The problem is exaggerated"],"answer_index":1,"explanation_vi":"Câu điều kiện đảo ngữ ngụ ý rằng hành động sớm hơn có thể đã tránh được sự phẫn nộ."}]}', 'course', 1, 'b2-overtourism', 'travel', 28)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'The Five-Dollar T-Shirt', 'The true cost of fast fashion', 'B2', '{"title":"The Five-Dollar T-Shirt","summary_vi":"Luyện nghe và đọc một bài nói kiểu podcast về tác động của thời trang nhanh lên môi trường và người lao động.","sentences":["Welcome back to the show.","Today I want to talk about the T-shirt you bought for the price of a coffee.","Fast fashion thrives on speed, turning catwalk trends into cheap clothes in a matter of weeks.","The industry now produces roughly twice as many garments as it did twenty years ago.","Much of that clothing is worn only a handful of times before it ends up in landfill.","A single pair of jeans can consume thousands of litres of water, while textile dyeing pollutes rivers in many countries.","Synthetic fibres such as polyester shed microplastics every time they are washed.","Meanwhile, the workers who stitch these garments are often paid wages that barely cover rent.","It would be easy to blame shoppers, but the system is designed to make buying feel effortless.","If brands were held accountable for the waste they create, prices would probably reflect the real cost.","Until then, the most sustainable garment is the one already hanging in your wardrobe.","So before you hit the buy button, ask yourself whether you will still love it in thirty wears."],"vocabulary":[{"word":"thrives on","ipa":"/θraɪvz ɑːn/","pos":"phrasal verb","meaning_vi":"phát triển mạnh nhờ vào","example":"Social media thrives on attention and quick reactions."},{"word":"in a matter of weeks","ipa":"/ɪn ə ˈmætər əv wiːks/","pos":"phrase","meaning_vi":"chỉ trong vài tuần","example":"The little shop became famous in a matter of weeks."},{"word":"ends up in landfill","ipa":"/ɛndz ʌp ɪn ˈlændfɪl/","pos":"phrase","meaning_vi":"cuối cùng bị đổ ra bãi rác","example":"Most plastic packaging ends up in landfill within a year."},{"word":"shed","ipa":"/ʃɛd/","pos":"verb","meaning_vi":"rụng ra, thải ra","example":"My cat sheds hair all over the sofa in summer."},{"word":"barely cover","ipa":"/ˈbɛrli ˈkʌvər/","pos":"phrase","meaning_vi":"chỉ vừa đủ trang trải","example":"Her scholarship will barely cover her tuition, let alone living costs."},{"word":"held accountable","ipa":"/hɛld əˈkaʊntəbəl/","pos":"phrase","meaning_vi":"bị buộc phải chịu trách nhiệm","example":"Company directors should be held accountable for serious safety failures."},{"word":"sustainable","ipa":"/səˈsteɪnəbəl/","pos":"adjective","meaning_vi":"bền vững, thân thiện với môi trường","example":"Bamboo is a sustainable alternative to plastic straws."}],"questions":[{"question":"How does fast fashion work, according to the speaker?","options":["It makes clothes designed to last decades","It copies trends and sells them cheaply within weeks","It sells only in luxury stores","It produces fewer clothes every year"],"answer_index":1,"explanation_vi":"Thời trang nhanh biến xu hướng sàn diễn thành quần áo giá rẻ chỉ trong vài tuần."},{"question":"Which environmental problem is linked to washing synthetic clothes?","options":["Air pollution","Microplastics entering waterways","Soil erosion","Noise pollution"],"answer_index":1,"explanation_vi":"Sợi tổng hợp như polyester thải ra vi nhựa mỗi lần giặt."},{"question":"What does the speaker say about blaming shoppers?","options":["Shoppers are the only cause","It is easy, but the system is built to encourage buying","Shoppers have no choice at all","Brands never advertise"],"answer_index":1,"explanation_vi":"Người nói cho rằng hệ thống được thiết kế để việc mua sắm trở nên dễ dàng nên không chỉ đổ lỗi cho người mua."},{"question":"What is the speaker''s final advice?","options":["Never buy clothes again","Buy only the cheapest items","Think about long-term use before buying","Give old clothes to the factory"],"answer_index":2,"explanation_vi":"Người nói khuyên tự hỏi liệu mình còn thích món đồ sau ba mươi lần mặc hay không."}]}', 'course', 1, 'b2-fast-fashion', 'nature', 29)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Pause, Rewind, Repeat', 'Online learning versus the classroom', 'B2', '{"title":"Pause, Rewind, Repeat","summary_vi":"Luyện nghe và đọc một bài bình luận so sánh học trực tuyến với học trên lớp, cùng các liên từ nối ý quan trọng.","sentences":["When classes moved online in 2020, I assumed it would be a temporary inconvenience.","Five years on, I am a university lecturer in Hanoi who teaches half of her courses through a screen.","Online learning has undeniably widened access, allowing a farmer''s daughter in Gia Lai to attend lectures from top universities.","It also lets students learn at their own pace, pausing and replaying a difficult explanation as often as they need.","Yet I have noticed that motivation tends to evaporate without the structure of a physical timetable.","Completion rates for free courses are strikingly low, often falling below ten percent.","In a classroom, a confused face is noticed immediately, whereas on a video call it is easily hidden behind a muted camera.","Casual conversations in corridors, which shape friendships and ideas, are almost impossible to replicate online.","That said, I would not want to go back to a purely traditional model.","The best results come from blended learning, where lectures are watched at home and class time goes on discussion.","Whichever format is chosen, success depends less on the technology than on the quality of the teaching.","A mediocre lecture does not become inspiring simply because it is streamed."],"vocabulary":[{"word":"widened access","ipa":"/ˈwaɪdənd ˈæksɛs/","pos":"phrase","meaning_vi":"mở rộng khả năng tiếp cận","example":"Public libraries have widened access to books for poor families."},{"word":"at their own pace","ipa":"/æt ðɛr oʊn peɪs/","pos":"phrase","meaning_vi":"theo tốc độ của riêng mình","example":"Children should be allowed to read at their own pace."},{"word":"evaporate","ipa":"/ɪˈvæpəreɪt/","pos":"verb","meaning_vi":"tan biến, bay mất","example":"My enthusiasm began to evaporate after the third rainy day."},{"word":"completion rates","ipa":"/kəmˈpliːʃən reɪts/","pos":"noun","meaning_vi":"tỷ lệ hoàn thành","example":"Completion rates rise when courses include short quizzes."},{"word":"replicate","ipa":"/ˈrɛplɪkeɪt/","pos":"verb","meaning_vi":"tái tạo, sao chép lại","example":"No app can replicate the atmosphere of a live concert."},{"word":"blended learning","ipa":"/ˈblɛndɪd ˈlɜːrnɪŋ/","pos":"noun","meaning_vi":"học kết hợp (trực tuyến và trực tiếp)","example":"Our school adopted blended learning to make better use of class time."},{"word":"that said","ipa":"/ðæt sɛd/","pos":"phrase","meaning_vi":"tuy nhiên, dẫu vậy","example":"The film was too long; that said, the ending was brilliant."}],"questions":[{"question":"What is one advantage of online learning mentioned?","options":["It is always cheaper than school","It lets students from remote areas attend top lectures","It removes the need for teachers","It guarantees better grades"],"answer_index":1,"explanation_vi":"Học trực tuyến giúp cả những học sinh ở vùng xa tham dự bài giảng của trường hàng đầu."},{"question":"Why does the writer say a confused student is harder to spot online?","options":["Students never ask questions","Cameras and microphones can be switched off","Lectures are too short","Teachers avoid eye contact"],"answer_index":1,"explanation_vi":"Sinh viên có thể tắt camera hoặc micro nên khó nhận ra vẻ bối rối."},{"question":"What does the writer prefer?","options":["Purely online courses","Purely traditional classrooms","A mix of home lectures and in-class discussion","Free courses only"],"answer_index":2,"explanation_vi":"Tác giả thấy kết quả tốt nhất đến từ mô hình học kết hợp."},{"question":"What is the point of the last sentence?","options":["Streaming makes lessons more fun","Technology cannot fix poor teaching","Lectures should be shorter","Video lessons are always mediocre"],"answer_index":1,"explanation_vi":"Bài giảng tệ không thể trở nên hay chỉ vì được phát trực tuyến."}]}', 'course', 1, 'b2-online-learning', 'study', 30)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'The Cinema in My Pocket', 'How streaming changed movies', 'B2', '{"title":"The Cinema in My Pocket","summary_vi":"Luyện nghe và đọc một bài tiểu luận cá nhân về việc các nền tảng phát trực tuyến thay đổi ngành điện ảnh và thói quen xem phim.","sentences":["As a teenager, I once queued for two hours to see a film that had already been out abroad for months.","Today the same film would be waiting on my phone before I finished my breakfast.","Streaming platforms have turned the entertainment industry upside down in barely fifteen years.","Studios that once relied on box office takings now compete for monthly subscriptions.","As a result, thousands of hours of content are made every year, and audiences are spoilt for choice.","This has opened doors for stories from outside Hollywood, such as Korean dramas and Spanish thrillers that found global fans overnight.","Directors enjoy bigger budgets and more creative freedom than they would have been given by a traditional studio.","On the other hand, the sheer volume makes it hard for quieter films to get noticed.","Shows are cancelled after one season if the algorithm decides they are not worth the gamble.","Cinemas have suffered too, although the best ones have survived by offering an experience that a sofa cannot match.","Personally, I binge-watch more than I would like to admit, and I rarely remember what I have seen.","Perhaps the real luxury today is not having more choice, but having the patience to choose well."],"vocabulary":[{"word":"upside down","ipa":"/ˈʌpsaɪd daʊn/","pos":"adverb","meaning_vi":"đảo lộn hoàn toàn","example":"The pandemic turned our travel plans upside down."},{"word":"box office","ipa":"/bɑːks ˈɑːfɪs/","pos":"noun","meaning_vi":"doanh thu phòng vé","example":"The sequel was a huge success at the box office."},{"word":"spoilt for choice","ipa":"/spɔɪlt fər tʃɔɪs/","pos":"idiom","meaning_vi":"có quá nhiều lựa chọn","example":"In this street food market, you are spoilt for choice."},{"word":"overnight","ipa":"/ˌoʊvərˈnaɪt/","pos":"adverb","meaning_vi":"chỉ sau một đêm, rất nhanh","example":"The young singer became famous overnight after one video."},{"word":"creative freedom","ipa":"/kriˈeɪtɪv ˈfriːdəm/","pos":"noun","meaning_vi":"sự tự do sáng tạo","example":"The writer accepted the job because she was given complete creative freedom."},{"word":"the sheer volume","ipa":"/ðə ʃɪr ˈvɑːljuːm/","pos":"phrase","meaning_vi":"khối lượng quá lớn","example":"The sheer volume of emails made it impossible to reply to everyone."},{"word":"worth the gamble","ipa":"/wɜːrθ ðə ˈɡæmbəl/","pos":"phrase","meaning_vi":"đáng để mạo hiểm","example":"Opening a restaurant in a quiet town seemed worth the gamble."}],"questions":[{"question":"What contrast does the writer open with?","options":["Cinema tickets were once cheaper","Waiting for films used to take much longer","Films used to be shorter","Teenagers watched fewer films"],"answer_index":1,"explanation_vi":"Trước đây phải xếp hàng và chờ hàng tháng, nay phim có sẵn ngay trên điện thoại."},{"question":"What benefit of streaming is described?","options":["Directors always earn more","Films are always better","Cinemas are more popular","Stories from outside Hollywood can reach a global audience"],"answer_index":3,"explanation_vi":"Phim Hàn và phim Tây Ban Nha tìm được khán giả toàn cầu nhờ các nền tảng."},{"question":"Why might quieter films struggle on streaming platforms?","options":["There is so much content that they are overlooked","Algorithms ban them","They are too expensive to make","Viewers dislike subtitles"],"answer_index":0,"explanation_vi":"Khối lượng nội dung khổng lồ khiến phim nhỏ khó được chú ý."},{"question":"What is the writer''s attitude in the final sentence?","options":["Excited about more choice","Angry at the platforms","Reflective, valuing patience over quantity","Uninterested in films"],"answer_index":2,"explanation_vi":"Tác giả suy ngẫm rằng điều quý giá là biết chọn lọc chứ không phải có thêm lựa chọn."}]}', 'course', 1, 'b2-streaming', 'fun', 31)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Sleep Is Not Wasted Time', 'Why we need more sleep', 'B2', '{"title":"Sleep Is Not Wasted Time","summary_vi":"Luyện nghe và đọc một bản tin khoa học về tầm quan trọng của giấc ngủ, cùng từ vựng về sức khỏe và thói quen sinh hoạt.","sentences":["Sleep used to be treated as wasted time, something ambitious people could cut down to make room for success.","Research over the past two decades has overturned that belief.","During deep sleep, the brain clears away waste products and moves the day''s memories into long-term storage.","Adults who regularly get less than six hours are more likely to develop heart disease and depression.","Even a single bad night can dull attention, much like drinking a couple of glasses of wine.","Teenagers are especially vulnerable, since their body clocks naturally shift later, yet school often starts at dawn.","Several districts that delayed the first bell by an hour reported better grades and fewer car accidents.","Dr Ana Ferreira, a sleep researcher in Lisbon, says people routinely underestimate how impaired they are.","\"If you need an alarm and a coffee to function, you are probably carrying a sleep debt,\" she explains.","Simple habits help: a consistent bedtime, a cool dark room and no screens for an hour beforehand.","None of this is glamorous, but it works better than any supplement on the market.","In short, a good night''s sleep is not a luxury; it is the foundation on which everything else is built."],"vocabulary":[{"word":"cut down","ipa":"/kʌt daʊn/","pos":"phrasal verb","meaning_vi":"cắt giảm","example":"The doctor told him to cut down on salt and sugar."},{"word":"overturned","ipa":"/ˌoʊvərˈtɜːrnd/","pos":"verb","meaning_vi":"lật đổ, bác bỏ","example":"The new evidence overturned the court''s earlier decision."},{"word":"vulnerable","ipa":"/ˈvʌlnərəbəl/","pos":"adjective","meaning_vi":"dễ bị tổn thương","example":"Elderly people are more vulnerable to extreme heat."},{"word":"body clocks","ipa":"/ˈbɑːdi klɑːks/","pos":"noun","meaning_vi":"đồng hồ sinh học","example":"Flying across time zones confuses our body clocks for days."},{"word":"underestimate","ipa":"/ˌʌndərˈɛstɪmeɪt/","pos":"verb","meaning_vi":"đánh giá thấp","example":"Never underestimate the power of a good night''s rest."},{"word":"sleep debt","ipa":"/sliːp dɛt/","pos":"noun","meaning_vi":"nợ ngủ (thiếu ngủ tích lũy)","example":"A weekend lie-in cannot repay months of sleep debt."},{"word":"in short","ipa":"/ɪn ʃɔːrt/","pos":"phrase","meaning_vi":"tóm lại","example":"The plan was costly and slow; in short, it was a mistake."}],"questions":[{"question":"What did research over the last two decades show?","options":["Sleep can be shortened without harm","Sleep is essential, not wasted time","Only teenagers need sleep","Coffee replaces sleep"],"answer_index":1,"explanation_vi":"Nghiên cứu đã bác bỏ quan niệm coi giấc ngủ là thời gian lãng phí."},{"question":"What happens in the brain during deep sleep?","options":["It stops working entirely","It forgets old skills","It stores memories and clears waste","It produces caffeine"],"answer_index":2,"explanation_vi":"Trong giấc ngủ sâu, não dọn chất thải và đưa ký ức vào kho lưu trữ dài hạn."},{"question":"Why are teenagers especially at risk?","options":["They dislike school","They sleep too much","They drink more wine","Their body clocks shift later but school starts early"],"answer_index":3,"explanation_vi":"Đồng hồ sinh học của thiếu niên lệch muộn trong khi giờ học bắt đầu rất sớm."},{"question":"What does Dr Ferreira imply about people who rely on alarms and coffee?","options":["They probably do not get enough sleep","They are healthier than average","They should sleep less","They have no sleep problems"],"answer_index":0,"explanation_vi":"Cô cho rằng cần báo thức và cà phê để tỉnh táo là dấu hiệu đang nợ giấc ngủ."}]}', 'course', 1, 'b2-sleep-science', 'health', 32)
