  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Know Your Worth', 'Negotiating a salary', 'C1', '{"title":"Know Your Worth","summary_vi":"Luyện cách trình bày và thương lượng mức lương một cách tự tin, tinh tế bằng tiếng Anh.","sentences":["Most people dread the moment when an employer asks, \"So, what are you looking for?\"","Yet it is precisely at that point that your leverage is greatest, provided you have done your homework.","Never walk into a negotiation without a clear sense of the going rate for your role and city.","Should the first figure they offer fall short, resist the urge to accept it out of sheer relief.","Anchoring is powerful: whoever names a number first tends to shape the entire conversation that follows.","Rather than demanding more, frame your request around the value you will bring to the team.","It is not the salary alone that matters, but the whole package, including bonuses, flexibility and training budgets.","If the company genuinely cannot stretch its budget, you can still negotiate a formal review in six months.","In Hanoi and Singapore alike, hiring managers expect some back-and-forth, and a polite counteroffer rarely offends anyone.","What truly undermines candidates is not asking too much, but apologising for asking at all.","Stay composed, let silence work in your favour, and be prepared to walk away if the terms are unreasonable.","Remember that a well-handled negotiation signals precisely the confidence employers hope to see in their future colleagues."],"vocabulary":[{"word":"leverage","ipa":"/ˈlɛvərɪdʒ/","pos":"noun","meaning_vi":"lợi thế để thương lượng","example":"Having a competing job offer gave her real leverage during the talks."},{"word":"going rate","ipa":"/ˈɡoʊɪŋ reɪt/","pos":"noun","meaning_vi":"mức giá/lương phổ biến hiện hành","example":"Freelance designers in this city charge the going rate of about fifty dollars an hour."},{"word":"fall short","ipa":"/fɔl ʃɔrt/","pos":"phrase","meaning_vi":"không đạt kỳ vọng","example":"If the proposal should fall short of our expectations, we will ask for revisions."},{"word":"anchoring","ipa":"/ˈæŋkərɪŋ/","pos":"noun","meaning_vi":"hiệu ứng neo giá","example":"Anchoring explains why the first price on a menu colours how expensive the rest seems."},{"word":"counteroffer","ipa":"/ˈkaʊntərˌɔfər/","pos":"noun","meaning_vi":"đề nghị phản hồi lại","example":"After a short pause, the buyer made a counteroffer that was ten percent lower."},{"word":"back-and-forth","ipa":"/ˌbæk ən ˈfɔrθ/","pos":"noun","meaning_vi":"sự trao đổi qua lại","example":"After weeks of back-and-forth, the two firms finally signed the contract."},{"word":"walk away","ipa":"/wɔk əˈweɪ/","pos":"phrase","meaning_vi":"rút lui, từ chối thỏa thuận","example":"A good negotiator knows when to walk away from a deal that does not add up."}],"questions":[{"question":"What is the main purpose of the passage?","options":["To warn candidates against changing jobs","To offer practical advice on negotiating pay","To compare salaries in different countries","To criticise how employers hire"],"answer_index":1,"explanation_vi":"Bài viết đưa ra lời khuyên thực tế về cách thương lượng lương."},{"question":"According to the passage, why does anchoring matter?","options":["It makes employers feel more generous","It lets candidates avoid awkward silences","The first number named tends to shape the discussion","It guarantees a higher final salary"],"answer_index":2,"explanation_vi":"Người nêu con số đầu tiên thường định hướng cả cuộc trao đổi."},{"question":"What does the writer say damages a candidate''s position most?","options":["Asking for too much money","Arriving without a counteroffer","Staying silent during talks","Apologising for making a request"],"answer_index":3,"explanation_vi":"Tác giả cho rằng việc xin lỗi vì đã đề nghị mới là điều gây bất lợi nhất."},{"question":"What option is suggested if the budget cannot be increased?","options":["Negotiating a review after six months","Accepting the first offer gratefully","Asking for a longer probation period","Moving to a different city"],"answer_index":0,"explanation_vi":"Nếu ngân sách hạn chế, có thể thương lượng một cuộc xem xét lại sau sáu tháng."}]}', 'course', 1, 'c1-salary-negotiation', 'work', 33)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Who Answers to the Algorithm?', 'The ethics of artificial intelligence', 'C1', '{"title":"Who Answers to the Algorithm?","summary_vi":"Luyện đọc và thảo luận về các vấn đề đạo đức của trí tuệ nhân tạo với từ vựng học thuật.","sentences":["Artificial intelligence is no longer a distant promise; it already decides who gets a loan, an interview or a medical scan.","That reach raises an uncomfortable question: who is accountable when an algorithm gets it wrong?","Bias is the most cited concern, and with good reason, since models learn from data that reflects historical prejudice.","A hiring tool trained on past decisions may quietly penalise women, simply because fewer of them were hired before.","Transparency offers a partial remedy, yet many systems remain black boxes even to the engineers who built them.","Were companies required to explain automated decisions, public trust would arguably be easier to earn.","Privacy poses a separate dilemma, because the data that makes these tools useful is often collected without meaningful consent.","Others worry less about present harms than about the long-term erosion of human judgement and skills.","Regulation is therefore taking shape, though lawmakers struggle to keep pace with a technology that evolves almost monthly.","In Vietnam, as elsewhere, the debate is shifting from whether to adopt AI to how to govern it responsibly.","Ultimately, it is not the machines that hold values, but the people who design, deploy and oversee them."],"vocabulary":[{"word":"accountable","ipa":"/əˈkaʊntəbəl/","pos":"adjective","meaning_vi":"phải chịu trách nhiệm","example":"Managers must be held accountable for the decisions their teams make."},{"word":"bias","ipa":"/ˈbaɪəs/","pos":"noun","meaning_vi":"thiên kiến, sự thiên vị","example":"The study found a clear bias against older applicants."},{"word":"black boxes","ipa":"/blæk ˈbɑksəz/","pos":"noun","meaning_vi":"hệ thống \"hộp đen\" khó giải thích","example":"Deep neural networks are often described as black boxes because their reasoning is hidden."},{"word":"meaningful consent","ipa":"/ˈminɪŋfəl kənˈsɛnt/","pos":"noun","meaning_vi":"sự đồng ý có hiểu biết thực sự","example":"Clicking \"accept\" on a thirty-page policy hardly amounts to meaningful consent."},{"word":"erosion","ipa":"/ɪˈroʊʒən/","pos":"noun","meaning_vi":"sự xói mòn","example":"Critics fear the erosion of trust in the news media."},{"word":"keep pace with","ipa":"/kip peɪs wɪð/","pos":"phrase","meaning_vi":"theo kịp","example":"Schools are struggling to keep pace with the speed of technological change."},{"word":"deploy","ipa":"/dɪˈplɔɪ/","pos":"verb","meaning_vi":"triển khai, đưa vào sử dụng","example":"The bank plans to deploy the new fraud-detection system next spring."}],"questions":[{"question":"Why does the writer say bias is a serious concern in AI?","options":["Engineers deliberately introduce it","Models learn from data that carries past prejudice","Users rarely read the results","It only affects financial services"],"answer_index":1,"explanation_vi":"Mô hình học từ dữ liệu phản ánh định kiến trong quá khứ."},{"question":"What does the hiring-tool example illustrate?","options":["A system copying historical unfairness","A tool that is too expensive to run","Women refusing to apply for jobs","Faster recruitment for large firms"],"answer_index":0,"explanation_vi":"Ví dụ cho thấy hệ thống lặp lại sự bất công vốn có trong dữ liệu cũ."},{"question":"What is the writer''s attitude towards regulation?","options":["Dismissive of its value","Certain that it will fail","Cautiously accepting but aware of its limits","Strongly opposed to new laws"],"answer_index":2,"explanation_vi":"Tác giả ghi nhận quy định đang hình thành nhưng thừa nhận khó theo kịp công nghệ."},{"question":"What is the main message of the final sentence?","options":["Machines will eventually develop values","Governments should ban AI","Companies are not responsible for software","Human beings remain responsible for AI"],"answer_index":3,"explanation_vi":"Câu cuối nhấn mạnh con người mới là bên chịu trách nhiệm về AI."}]}', 'course', 1, 'c1-ai-ethics', 'tech', 34)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Concrete Meets Canopy', 'Designing greener cities', 'C1', '{"title":"Concrete Meets Canopy","summary_vi":"Luyện đọc bài phóng sự về thiết kế đô thị xanh với các cụm từ nâng cao về môi trường.","sentences":["Walk through Singapore''s Gardens by the Bay and it becomes obvious that concrete and nature need not be enemies.","Cities occupy a small fraction of the planet''s land, yet they account for most of its energy consumption.","That imbalance is why planners are now rethinking streets, rooftops and even the humble pavement.","Green roofs absorb rainwater, insulate buildings and, perhaps most importantly, cool the air around them.","Cities like Copenhagen have gone further, redesigning entire districts so that heavy downpours drain into parks rather than basements.","Ho Chi Minh City, with its chronic flooding and punishing summers, has much to gain from such measures.","It is not enough, however, to plant trees and call the job done.","Without maintenance and thoughtful species selection, new greenery can wither, wasting both money and public goodwill.","Transport matters just as much; the more people cycle, walk or ride trains, the less smog settles over the skyline.","Critics warn that greening can trigger gentrification, pushing out the very residents it was meant to serve.","Addressing that risk requires affordable housing policies to be woven into the design from the outset.","A truly sustainable city, in other words, is one that is liveable for everyone, not merely photogenic."],"vocabulary":[{"word":"account for","ipa":"/əˈkaʊnt fɔr/","pos":"phrase","meaning_vi":"chiếm (một tỷ lệ)","example":"Cars account for nearly half of the city''s air pollution."},{"word":"insulate","ipa":"/ˈɪnsəˌleɪt/","pos":"verb","meaning_vi":"cách nhiệt","example":"Thick walls insulate the old house against the summer heat."},{"word":"downpours","ipa":"/ˈdaʊnˌpɔrz/","pos":"noun","meaning_vi":"những trận mưa như trút","example":"Sudden downpours turned the streets into rivers within minutes."},{"word":"chronic","ipa":"/ˈkrɑnɪk/","pos":"adjective","meaning_vi":"kinh niên, kéo dài","example":"Chronic traffic congestion costs the economy millions every year."},{"word":"wither","ipa":"/ˈwɪðər/","pos":"verb","meaning_vi":"héo úa, tàn lụi","example":"Without regular watering, the young saplings will wither."},{"word":"gentrification","ipa":"/ˌdʒɛntrəfɪˈkeɪʃən/","pos":"noun","meaning_vi":"hiện tượng tầng lớp giàu đẩy giá khiến dân cũ phải rời đi","example":"Rapid gentrification has made the old quarter unaffordable for many families."},{"word":"from the outset","ipa":"/frəm ði ˈaʊtˌsɛt/","pos":"phrase","meaning_vi":"ngay từ đầu","example":"The architect made it clear from the outset that the budget was tight."}],"questions":[{"question":"What contrast does the second sentence draw?","options":["City size versus population","Small land area versus large energy use","Old buildings versus new ones","Rich cities versus poor ones"],"answer_index":1,"explanation_vi":"Thành phố chiếm ít đất nhưng tiêu thụ phần lớn năng lượng."},{"question":"Why does the writer mention Ho Chi Minh City?","options":["To criticise its transport system","To praise its parks","To show it could benefit from green measures","To compare it with Copenhagen''s budget"],"answer_index":2,"explanation_vi":"Thành phố này chịu ngập và nóng nên được lợi từ các giải pháp xanh."},{"question":"What risk of greening do critics identify?","options":["Higher smog levels","Fewer cyclists","Wasted rainwater","Pushing out existing residents"],"answer_index":3,"explanation_vi":"Các nhà phê bình lo việc làm xanh gây gentrification, đẩy dân cũ đi."},{"question":"What is implied by the last sentence?","options":["Sustainability must include social fairness","Beauty matters more than function","Only wealthy cities can go green","Photogenic cities attract more tourists"],"answer_index":0,"explanation_vi":"Thành phố bền vững phải dễ sống cho mọi người, không chỉ đẹp."}]}', 'course', 1, 'c1-green-cities', 'nature', 35)
