INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'The Mind''s Shortcuts', 'Cognitive biases in everyday decisions', 'C1', '{"title":"The Mind''s Shortcuts","summary_vi":"Luyện đọc bài suy ngẫm về các thiên kiến nhận thức ảnh hưởng đến quyết định hằng ngày.","sentences":["We like to imagine that our decisions flow from careful reasoning, but the mind prefers shortcuts.","Psychologists call these shortcuts heuristics, and while they save time, they also leave us prone to systematic error.","Take confirmation bias: once we hold a belief, we instinctively seek out evidence that supports it.","Rarely do we notice how selectively we read the news, or whom we choose to listen to.","Then there is the sunk cost fallacy, which keeps people in failing projects simply because they have already invested so much.","I once sat through an entire dreadful film for precisely that reason, having paid for the ticket.","Anchoring is subtler still, since an arbitrary first number can distort every estimate that follows.","Knowing about these traps does not make us immune; if anything, it can breed overconfidence.","What helps is slowing down, particularly when the stakes are high and emotions are running hot.","Asking a trusted friend to challenge your reasoning, or writing down your assumptions, can expose blind spots.","We will never be perfectly rational, but we can learn to catch ourselves in the act."],"vocabulary":[{"word":"prone to","ipa":"/proʊn tu/","pos":"adjective","meaning_vi":"dễ bị, có xu hướng","example":"Tired drivers are more prone to making serious mistakes."},{"word":"confirmation bias","ipa":"/ˌkɑnfərˈmeɪʃən ˈbaɪəs/","pos":"noun","meaning_vi":"thiên kiến xác nhận","example":"Confirmation bias leads us to share only the articles that agree with us."},{"word":"sunk cost fallacy","ipa":"/sʌŋk kɔst ˈfæləsi/","pos":"noun","meaning_vi":"ngụy biện chi phí chìm","example":"Staying in a bad investment because of past losses is the sunk cost fallacy in action."},{"word":"arbitrary","ipa":"/ˈɑrbəˌtrɛri/","pos":"adjective","meaning_vi":"tùy tiện, ngẫu nhiên","example":"The deadline seemed arbitrary, since nobody could explain how it was chosen."},{"word":"breed","ipa":"/brid/","pos":"verb","meaning_vi":"gây ra, nuôi dưỡng","example":"Constant praise can breed complacency in a young team."},{"word":"the stakes are high","ipa":"/ðə steɪks ɑr haɪ/","pos":"idiom","meaning_vi":"rủi ro/được mất rất lớn","example":"Before a final exam, the stakes are high and even small errors feel enormous."},{"word":"blind spots","ipa":"/blaɪnd spɑts/","pos":"noun","meaning_vi":"điểm mù, thiếu sót không nhận ra","example":"Honest feedback helps leaders identify their blind spots."}],"questions":[{"question":"What does the writer suggest about heuristics?","options":["They are always harmful","They save time but can mislead us","They only affect experts","They have been scientifically disproved"],"answer_index":1,"explanation_vi":"Heuristics tiết kiệm thời gian nhưng khiến ta dễ mắc lỗi có hệ thống."},{"question":"Why does the writer mention watching a dreadful film?","options":["To recommend a particular movie","To criticise cinema ticket prices","To illustrate a bias with a personal example","To show how little they value money"],"answer_index":2,"explanation_vi":"Đó là ví dụ cá nhân minh họa cho ngụy biện chi phí chìm."},{"question":"What ironic point is made about knowing these biases?","options":["Awareness can make us overconfident","Awareness eliminates all errors","Biases only affect the uninformed","Awareness makes decisions slower"],"answer_index":0,"explanation_vi":"Biết về thiên kiến không giúp miễn nhiễm, thậm chí có thể gây tự tin quá mức."},{"question":"What is the tone of the final sentence?","options":["Angry and accusing","Doubtful and confused","Mocking and sarcastic","Realistic and gently hopeful"],"answer_index":3,"explanation_vi":"Câu cuối thừa nhận sự không hoàn hảo nhưng vẫn lạc quan nhẹ nhàng."}]}', 'course', 1, 'c1-cognitive-bias', 'people', 36)
