INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Butterflies in Formation', 'Speaking in public with confidence', 'C1', '{"title":"Butterflies in Formation","summary_vi":"Luyện nghe và nói theo một bài phát biểu về cách tự tin khi nói trước đám đông.","sentences":["Good evening, everyone, and thank you for coming; I promise to keep my nerves in check.","Let me begin with a confession: for years, I would rather have done almost anything than speak in public.","My palms would sweat, my voice would tremble, and my carefully prepared words would vanish.","What changed was not that the fear disappeared, but that I learned to reinterpret it.","Those butterflies are simply your body gearing up for a challenge, and a little adrenaline sharpens focus.","Preparation matters, of course, yet over-rehearsing every word can make you sound stilted and robotic.","I now build my talks around three key ideas, which gives me something solid to fall back on.","Pausing is the most underrated skill; a well-placed silence lets your point sink in.","Equally important is eye contact, because speaking to individuals feels far less daunting than addressing a crowd.","Should you stumble, don''t panic; audiences are remarkably forgiving when a speaker simply carries on.","Above all, remember that people are not there to judge you, but to hear what you have to say.","Thank you; now, I''d be glad to take your questions."],"vocabulary":[{"word":"in check","ipa":"/ɪn tʃɛk/","pos":"phrase","meaning_vi":"được kiểm soát","example":"She kept her anger in check throughout the heated meeting."},{"word":"gearing up for","ipa":"/ˈɡɪrɪŋ ʌp fɔr/","pos":"phrase","meaning_vi":"chuẩn bị cho","example":"The whole team is gearing up for next week''s product launch."},{"word":"stilted","ipa":"/ˈstɪltɪd/","pos":"adjective","meaning_vi":"gượng gạo, thiếu tự nhiên","example":"His stilted greeting made the atmosphere even more awkward."},{"word":"fall back on","ipa":"/fɔl bæk ɑn/","pos":"phrase","meaning_vi":"dựa vào khi cần","example":"Having savings gave her something to fall back on when the business struggled."},{"word":"sink in","ipa":"/sɪŋk ɪn/","pos":"phrase","meaning_vi":"được thấm, hiểu dần","example":"It took a few days for the news of the promotion to sink in."},{"word":"daunting","ipa":"/ˈdɔntɪŋ/","pos":"adjective","meaning_vi":"khiến nản lòng, đáng sợ","example":"Starting a new career at forty can feel daunting."},{"word":"underrated","ipa":"/ˌʌndərˈreɪtɪd/","pos":"adjective","meaning_vi":"bị đánh giá thấp","example":"Listening is an underrated skill in any leadership role."}],"questions":[{"question":"What kind of text is this passage most likely to be?","options":["A written complaint","A spoken talk to an audience","A newspaper report","A set of instructions"],"answer_index":1,"explanation_vi":"Lời chào, cảm ơn và mời đặt câu hỏi cho thấy đây là bài nói trước khán giả."},{"question":"How did the speaker''s attitude to fear change?","options":["She stopped feeling any fear","She avoided all speaking events","She learned to see it as useful energy","She relied entirely on notes"],"answer_index":2,"explanation_vi":"Cô học cách nhìn nỗi sợ như năng lượng hữu ích chứ không xóa bỏ nó."},{"question":"Why does the speaker warn against over-rehearsing?","options":["It wastes too much time","It makes the audience bored","It causes physical illness","It can make a talk sound unnatural"],"answer_index":3,"explanation_vi":"Tập quá kỹ từng chữ khiến bài nói nghe gượng gạo, như người máy."},{"question":"What does the speaker say about audiences?","options":["They are forgiving if you carry on after a mistake","They notice every error","They prefer very short talks","They judge speakers harshly"],"answer_index":0,"explanation_vi":"Khán giả khá bao dung khi diễn giả vẫn tiếp tục sau khi vấp."}]}', 'course', 1, 'c1-public-speaking', 'people', 37)
