INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'The Price of a Glance', 'The attention economy', 'C1', '{"title":"The Price of a Glance","summary_vi":"Luyện đọc bài luận về nền kinh tế chú ý và cách các nền tảng thu hút thời gian của chúng ta.","sentences":["If a service is free, the old saying goes, then you are the product.","Nowhere is that truer than in the attention economy, where your time and focus are the scarce currency.","Platforms compete fiercely to hold your gaze, and they have engineered features to do precisely that.","Endless scrolling, autoplay and notification badges are not accidents; they are carefully tested to keep you coming back.","The consequences are subtle but cumulative, as fragmented attention makes sustained, deep thinking harder to achieve.","Many Vietnamese teenagers now spend hours on short videos, often without recalling what they watched.","It would be unfair, though, to cast technology as the sole villain.","These tools connect families across oceans, democratise information and give small businesses a global stage.","The real issue is design that profits from compulsion rather than genuine value.","Some users are fighting back by switching off notifications, setting screen limits or reclaiming whole evenings offline.","Regulators, meanwhile, are asking whether manipulative design should face the same scrutiny as misleading advertising.","Until incentives change, the burden will keep falling on individuals to guard their own attention."],"vocabulary":[{"word":"scarce","ipa":"/skɛrs/","pos":"adjective","meaning_vi":"khan hiếm","example":"Fresh water is becoming scarce in many coastal regions."},{"word":"engineered","ipa":"/ˌɛndʒəˈnɪrd/","pos":"verb","meaning_vi":"được thiết kế có chủ đích","example":"The snack was engineered to be impossible to stop eating."},{"word":"cumulative","ipa":"/ˈkjumjələtɪv/","pos":"adjective","meaning_vi":"tích lũy dần","example":"The cumulative effect of poor sleep is hard to ignore."},{"word":"fragmented","ipa":"/ˈfræɡˌmɛntɪd/","pos":"adjective","meaning_vi":"bị chia nhỏ, rời rạc","example":"A fragmented schedule left her no time for deep work."},{"word":"democratise","ipa":"/dɪˈmɑkrəˌtaɪz/","pos":"verb","meaning_vi":"phổ cập cho mọi người","example":"Open courses aim to democratise access to higher education."},{"word":"compulsion","ipa":"/kəmˈpʌlʃən/","pos":"noun","meaning_vi":"sự thôi thúc khó cưỡng","example":"He checked his phone out of compulsion rather than need."},{"word":"scrutiny","ipa":"/ˈskrutəni/","pos":"noun","meaning_vi":"sự xem xét kỹ lưỡng","example":"The company''s accounts came under intense scrutiny after the scandal."}],"questions":[{"question":"What does \"you are the product\" suggest?","options":["Users receive free gifts","Companies profit from users'' attention and data","Free services are always high quality","Customers help design the product"],"answer_index":1,"explanation_vi":"Câu nói ngụ ý công ty kiếm lời từ sự chú ý và dữ liệu của người dùng."},{"question":"According to the writer, why are features like autoplay used?","options":["To save battery power","To teach users patience","To keep people returning and engaged","To reduce advertising costs"],"answer_index":2,"explanation_vi":"Các tính năng này được thử nghiệm kỹ để giữ người dùng quay lại."},{"question":"What is the writer''s overall view of technology?","options":["Entirely harmful","Largely irrelevant","Equally useful to all users","Beneficial but flawed by manipulative design"],"answer_index":3,"explanation_vi":"Tác giả công nhận lợi ích nhưng chỉ trích thiết kế thao túng."},{"question":"What does the final sentence imply?","options":["Individuals must protect their focus until incentives shift","Regulators have solved the problem","Teenagers are to blame","Platforms will soon change voluntarily"],"answer_index":0,"explanation_vi":"Chừng nào động cơ chưa đổi, cá nhân vẫn phải tự bảo vệ sự tập trung."}]}', 'course', 1, 'c1-attention-economy', 'tech', 38)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
