INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'More Than a Bowl', 'Food as cultural heritage', 'C1', '{"title":"More Than a Bowl","summary_vi":"Luyện đọc bài viết về ẩm thực như một di sản văn hóa với những cách diễn đạt tinh tế.","sentences":["A bowl of phở is never just a bowl of phở.","Behind its fragrant broth lies a century of migration, adaptation and fierce regional pride.","Food is among the most intimate ways a culture remembers itself, passed down not in books but in kitchens.","Grandmothers rarely measure ingredients; they rely on instinct, taste and a lifetime of repetition.","When such knowledge goes unrecorded, it can vanish within a single generation.","This is why UNESCO has begun recognising culinary traditions, from Neapolitan pizza to Korean kimchi-making, as intangible heritage.","Recognition, however, is a double-edged sword, since it may attract tourists who turn rituals into spectacle.","Street vendors in Huế, for instance, now compete with polished restaurants that serve imperial dishes in simplified form.","Purists argue that authenticity is being diluted, whereas others insist that cuisine has always evolved through borrowing.","Indeed, the bánh mì itself is a delicious product of colonial history and local ingenuity.","Perhaps the wisest approach is to document recipes faithfully while allowing cooks the freedom to improvise.","After all, a tradition that cannot breathe is merely a museum piece."],"vocabulary":[{"word":"passed down","ipa":"/pæst daʊn/","pos":"phrase","meaning_vi":"được truyền lại","example":"The recipe has been passed down in her family for five generations."},{"word":"intangible heritage","ipa":"/ɪnˈtændʒəbəl ˈhɛrɪtɪdʒ/","pos":"noun","meaning_vi":"di sản phi vật thể","example":"Folk songs are a precious form of intangible heritage."},{"word":"double-edged sword","ipa":"/ˌdʌbəl ɛdʒd ˈsɔrd/","pos":"idiom","meaning_vi":"con dao hai lưỡi","example":"Fame can be a double-edged sword for young chefs."},{"word":"authenticity","ipa":"/ˌɔθɛnˈtɪsəti/","pos":"noun","meaning_vi":"tính chân thực","example":"Diners often travel far in search of authenticity."},{"word":"diluted","ipa":"/daɪˈlutɪd/","pos":"verb","meaning_vi":"bị pha loãng, làm yếu đi","example":"The original message was diluted by endless compromises."},{"word":"ingenuity","ipa":"/ˌɪndʒəˈnuəti/","pos":"noun","meaning_vi":"sự khéo léo, sáng tạo","example":"The village cooks showed great ingenuity during the food shortage."},{"word":"improvise","ipa":"/ˈɪmprəˌvaɪz/","pos":"verb","meaning_vi":"ứng biến","example":"When the shop ran out of basil, she had to improvise with mint."}],"questions":[{"question":"What does the opening sentence suggest about phở?","options":["It is overrated abroad","It carries deep cultural meaning","It is too simple to describe","It was invented recently"],"answer_index":1,"explanation_vi":"Câu mở đầu ngụ ý phở mang nhiều ý nghĩa văn hóa hơn một món ăn."},{"question":"Why can culinary knowledge disappear so easily?","options":["Cooks refuse to share recipes","Ingredients are becoming rare","It is often unwritten and learned by instinct","Governments forbid traditional cooking"],"answer_index":2,"explanation_vi":"Kiến thức nấu ăn thường không được ghi lại mà truyền qua trực giác."},{"question":"Why is recognition called a double-edged sword?","options":["It makes recipes more expensive","It reduces the number of tourists","It encourages cooks to leave home","It can turn traditions into spectacle"],"answer_index":3,"explanation_vi":"Sự công nhận vừa bảo vệ vừa có thể biến nghi lễ thành màn trình diễn."},{"question":"What does the writer imply with the bánh mì example?","options":["Cuisine has long evolved through outside influences","Colonial food is inferior","Purists are always right","Sandwiches cannot be traditional"],"answer_index":0,"explanation_vi":"Bánh mì cho thấy ẩm thực vốn luôn tiến hóa nhờ vay mượn."}]}', 'course', 1, 'c1-food-heritage', 'food', 39)
