INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), 'Beginners Forever', 'Learning for life', 'C1', '{"title":"Beginners Forever","summary_vi":"Luyện đọc bài suy ngẫm về việc học suốt đời và cách duy trì sự tò mò khi trưởng thành.","sentences":["For much of the twentieth century, education was imagined as a front-loaded affair: study first, work later.","That model is fast becoming obsolete.","Technologies shift so rapidly that skills acquired at twenty can look dated by thirty-five.","Lifelong learning, once a fashionable slogan, has therefore become a practical necessity.","Yet learning as an adult is not simply schooling repeated; it demands different habits.","Adults juggle jobs, families and fatigue, so motivation must come from relevance rather than obligation.","Many find that small, consistent effort outperforms occasional bursts of ambitious cramming.","Curiosity, moreover, is a muscle that strengthens with use and atrophies with neglect.","In Vietnam, evening classes, online courses and community libraries are widening access to people who missed formal opportunities.","Still, accessibility alone does not guarantee progress without the willingness to be a beginner again.","That humility, I would argue, is the hardest part and the most rewarding.","Those who embrace it tend to adapt more gracefully when the world inevitably changes around them."],"vocabulary":[{"word":"front-loaded","ipa":"/ˌfrʌnt ˈloʊdɪd/","pos":"adjective","meaning_vi":"dồn hết vào giai đoạn đầu","example":"The course is front-loaded, with most of the hard material in the first month."},{"word":"obsolete","ipa":"/ˌɑbsəˈlit/","pos":"adjective","meaning_vi":"lỗi thời","example":"Typewriters became obsolete once personal computers arrived."},{"word":"practical necessity","ipa":"/ˈpræktɪkəl nəˈsɛsəti/","pos":"noun","meaning_vi":"nhu cầu thiết thực","example":"For commuters in a big city, a motorbike is a practical necessity."},{"word":"outperforms","ipa":"/ˌaʊtpərˈfɔrmz/","pos":"verb","meaning_vi":"làm tốt hơn, vượt trội hơn","example":"Steady practice usually outperforms last-minute revision."},{"word":"cramming","ipa":"/ˈkræmɪŋ/","pos":"noun","meaning_vi":"học nhồi nhét","example":"Cramming the night before an exam rarely leads to lasting knowledge."},{"word":"atrophies","ipa":"/ˈætrəfiz/","pos":"verb","meaning_vi":"teo đi, suy yếu","example":"A skill that is never practised slowly atrophies."},{"word":"humility","ipa":"/hjuˈmɪləti/","pos":"noun","meaning_vi":"sự khiêm tốn","example":"Real expertise often comes with a surprising amount of humility."}],"questions":[{"question":"What does the writer say about the traditional model of education?","options":["It is more effective than ever","It no longer suits a fast-changing world","It was never widely adopted","It should be extended to adults only"],"answer_index":1,"explanation_vi":"Mô hình học trước, làm sau đang trở nên lỗi thời."},{"question":"According to the passage, what should motivate adult learners?","options":["Pressure from employers","Competition with friends","Relevance to their own lives","Formal qualifications"],"answer_index":2,"explanation_vi":"Người lớn cần động lực đến từ sự liên quan, không phải nghĩa vụ."},{"question":"What does the metaphor of curiosity as a muscle suggest?","options":["Curiosity is a natural talent","Curiosity declines with age","Curiosity needs expensive training","It grows through use and fades if neglected"],"answer_index":3,"explanation_vi":"Tò mò như cơ bắp: dùng thì mạnh lên, bỏ bê thì yếu đi."},{"question":"What does the writer see as the hardest part of learning?","options":["Being willing to start as a beginner again","Finding enough time","Paying for courses","Travelling to classes"],"answer_index":0,"explanation_vi":"Tác giả cho rằng sự khiêm tốn làm người mới lại là phần khó nhất."}]}', 'course', 1, 'c1-lifelong-learning', 'study', 40)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
